insert into public.episodes (title_id, season_number, episode_number, name, runtime_minutes, synopsis, still_path)
select t, s, e, n, r, y, p from jsonb_to_recordset($json$[{"t":"breaking-bad","s":1,"e":1,"n":"Pilot","r":59,"y":"A mild-mannered Albuquerque chemistry teacher receives a grim medical diagnosis and turns to an unlikely partner, a former student, to secure his family's financial future.","p":"/assets/stills/breaking-bad-s1e1.jpg"},{"t":"breaking-bad","s":1,"e":2,"n":"Cat's in the Bag...","r":49,"y":"Reeling from their first deal gone wrong, the new partners scramble to clean up a dangerous mess while Walt's wife starts noticing his odd absences.","p":"/assets/stills/breaking-bad-s1e2.jpg"},{"t":"breaking-bad","s":1,"e":3,"n":"...And the Bag's in the River","r":49,"y":"Left to deal with a prisoner on his own, Walt wrestles with a moral dilemma as family tensions over Walt Jr. and his secrecy simmer at home.","p":"/assets/stills/breaking-bad-s1e3.jpg"},{"t":"breaking-bad","s":1,"e":4,"n":"Cancer Man","r":49,"y":"Walt finally shares his diagnosis with his relatives, the DEA senses a new supplier in town, and Jesse drops in on parents who have given up on him.","p":"/assets/stills/breaking-bad-s1e4.jpg"},{"t":"breaking-bad","s":1,"e":5,"n":"Gray Matter","r":49,"y":"At a party thrown by old friends from his past, Walt faces an offer he resents, while Jesse looks for a straighter life and the family stages an intervention.","p":"/assets/stills/breaking-bad-s1e5.jpg"},{"t":"breaking-bad","s":1,"e":6,"n":"Crazy Handful of Nothin'","r":49,"y":"Chemotherapy starts taking its toll on Walt, the DEA begins sweeping up street dealers, and the partners look for a bigger buyer for their product.","p":"/assets/stills/breaking-bad-s1e6.jpg"},{"t":"breaking-bad","s":1,"e":7,"n":"A No Rough Stuff Type Deal","r":48,"y":"Walt grows more comfortable in his criminal role, Jesse eyes his late aunt's house, and Skyler's baby shower brings the family together under strain.","p":"/assets/stills/breaking-bad-s1e7.jpg"},{"t":"breaking-bad","s":2,"e":1,"n":"Seven Thirty-Seven","r":48,"y":"Shaken by their volatile distributor, Walt and Jesse search for an escape route while Hank tries to patch up the rift between Marie and Skyler.","p":"/assets/stills/breaking-bad-s2e1.jpg"},{"t":"breaking-bad","s":2,"e":2,"n":"Grilled","r":48,"y":"Trapped at a remote hideout with an increasingly unstable Tuco, the partners fight to survive as Walt's family frantically wonders where he has gone.","p":"/assets/stills/breaking-bad-s2e2.jpg"},{"t":"breaking-bad","s":2,"e":3,"n":"Bit by a Dead Bee","r":47,"y":"Walt and Jesse need cash and a cover story after their ordeal, while the DEA follows evidence that edges closer to the pair.","p":"/assets/stills/breaking-bad-s2e3.jpg"},{"t":"breaking-bad","s":2,"e":4,"n":"Down","r":48,"y":"Walt tries to reconnect with a family that feels him slipping away, as Jesse hits rock bottom and attempts to rebuild his life from scratch.","p":"/assets/stills/breaking-bad-s2e4.jpg"},{"t":"breaking-bad","s":2,"e":5,"n":"Breakage","r":48,"y":"Hank struggles with the aftermath of a violent encounter, while Jesse recruits a small crew of dealers to move product on the streets.","p":"/assets/stills/breaking-bad-s2e5.jpg"},{"t":"breaking-bad","s":2,"e":6,"n":"Peekaboo","r":48,"y":"A thank-you from Skyler to the Schwartzes threatens to unravel Walt's story about his treatment, while Jesse collects a debt in a grim household.","p":"/assets/stills/breaking-bad-s2e6.jpg"},{"t":"breaking-bad","s":2,"e":7,"n":"Negro y Azul","r":48,"y":"The partners consider expanding their territory, Hank finds it hard to settle into a new post, Skyler explores a job, and Jesse warms to his landlord.","p":"/assets/stills/breaking-bad-s2e7.jpg"},{"t":"breaking-bad","s":2,"e":8,"n":"Better Call Saul","r":48,"y":"When Badger is arrested, Walt and Jesse turn to a flashy, morally flexible lawyer for help as the DEA believes it has located the elusive Heisenberg.","p":"/assets/stills/breaking-bad-s2e8.jpg"},{"t":"breaking-bad","s":2,"e":9,"n":"4 Days Out","r":48,"y":"As the family awaits scan results, Walt and Jesse head into the desert for a marathon cooking session that quickly goes sideways.","p":"/assets/stills/breaking-bad-s2e9.jpg"},{"t":"breaking-bad","s":2,"e":10,"n":"Over","r":48,"y":"Hoping to put his old life behind him, Walt quarrels with Hank at a celebration, Skyler confides in her boss, and Jane keeps Jesse a secret.","p":"/assets/stills/breaking-bad-s2e10.jpg"},{"t":"breaking-bad","s":2,"e":11,"n":"Mandala","r":48,"y":"A late-stage pregnancy leaves Skyler conflicted, and a sudden loss in the distribution network forces Walt to hunt for a new buyer with deep pockets.","p":"/assets/stills/breaking-bad-s2e11.jpg"},{"t":"breaking-bad","s":2,"e":12,"n":"Phoenix","r":48,"y":"Walt investigates ways to launder his earnings while he and Jesse argue over their cut, and Jane's father grows worried about the company she keeps.","p":"/assets/stills/breaking-bad-s2e12.jpg"},{"t":"breaking-bad","s":2,"e":13,"n":"ABQ","r":48,"y":"Skyler presses Walt about his lies, Jesse comes apart in grief, and a sorrowful father returns to work at a critical moment.","p":"/assets/stills/breaking-bad-s2e13.jpg"},{"t":"breaking-bad","s":3,"e":1,"n":"No Más","r":48,"y":"Facing an angry Skyler and an uncertain marriage, Walt contends with a new danger he does not yet see, while Jesse confronts hard truths in rehab.","p":"/assets/stills/breaking-bad-s3e1.jpg"},{"t":"breaking-bad","s":3,"e":2,"n":"Caballo sin Nombre","r":48,"y":"Walt goes to great lengths to win his family back despite the growing distance, while Saul steers Jesse toward an unusual investment.","p":"/assets/stills/breaking-bad-s3e2.jpg"},{"t":"breaking-bad","s":3,"e":3,"n":"I.F.T.","r":48,"y":"Defying Skyler's wishes, Walt refuses to keep his distance, pushing her to make a bold move of her own, as Hank's anxiety boils over on the job.","p":"/assets/stills/breaking-bad-s3e3.jpg"},{"t":"breaking-bad","s":3,"e":4,"n":"Green Light","r":48,"y":"Walt reacts badly to news from Skyler, straining his school job and his ties to Saul and Jesse, while Hank dives into the blue meth case.","p":"/assets/stills/breaking-bad-s3e4.jpg"},{"t":"breaking-bad","s":3,"e":5,"n":"Más","r":48,"y":"Gus works harder to bring Walt back into the business with a tempting offer, opening a rift with Jesse as Marie voices worry about Hank.","p":"/assets/stills/breaking-bad-s3e5.jpg"},{"t":"breaking-bad","s":3,"e":6,"n":"Sunset","r":48,"y":"Walt adjusts to an impressive new workplace while Walter Jr. demands answers and Hank's dogged investigation creates real trouble for the partners.","p":"/assets/stills/breaking-bad-s3e6.jpg"},{"t":"breaking-bad","s":3,"e":7,"n":"One Minute","r":48,"y":"Hank's temper leads to a damaging clash with Jesse and consequences at work, as Skyler leans on Walt to strike a deal and Gus makes a move.","p":"/assets/stills/breaking-bad-s3e7.jpg"},{"t":"breaking-bad","s":3,"e":8,"n":"I See You","r":48,"y":"The family keeps vigil at the hospital, Jesse holds the fort at the lab, and Walt grows alarmed about the safety of those he loves.","p":"/assets/stills/breaking-bad-s3e8.jpg"},{"t":"breaking-bad","s":3,"e":9,"n":"Kafkaesque","r":48,"y":"With medical bills mounting, Skyler devises a cover story for the family finances while Jesse pursues a side venture on his own terms.","p":"/assets/stills/breaking-bad-s3e9.jpg"},{"t":"breaking-bad","s":3,"e":10,"n":"Fly","r":48,"y":"Walt becomes fixated on a single fly that he believes is contaminating the lab, keeping a frustrated Jesse cooped up for an unusually reflective night.","p":"/assets/stills/breaking-bad-s3e10.jpg"},{"t":"breaking-bad","s":3,"e":11,"n":"Abiquiu","r":48,"y":"Skyler takes an interest in how Walt's money can be cleaned, Hank wrestles with his recovery, and Jesse makes a discovery after meeting someone in group.","p":"/assets/stills/breaking-bad-s3e11.jpg"},{"t":"breaking-bad","s":3,"e":12,"n":"Half Measures","r":48,"y":"Jesse wants to strike back at people who wronged him, ignoring Walt's warnings and forcing Walt to decide how far he will go to protect his partner.","p":"/assets/stills/breaking-bad-s3e12.jpg"},{"t":"breaking-bad","s":3,"e":13,"n":"Full Measure","r":48,"y":"With Jesse lying low and Mike on his trail, Walt bargains with Gus and devises a desperate plan to make himself and Jesse indispensable.","p":"/assets/stills/breaking-bad-s3e13.jpg"},{"t":"breaking-bad","s":4,"e":1,"n":"Box Cutter","r":48,"y":"Walt and Jesse sit in the lab facing the fallout of their recent choices, while Skyler wonders about Walt's whereabouts and Marie tends to Hank.","p":"/assets/stills/breaking-bad-s4e1.jpg"},{"t":"breaking-bad","s":4,"e":2,"n":"Thirty-Eight Snub","r":46,"y":"Walt looks for a way to protect himself from his employer, while Skyler nudges him toward a legitimate business that could launder their money.","p":"/assets/stills/breaking-bad-s4e2.jpg"},{"t":"breaking-bad","s":4,"e":3,"n":"Open House","r":47,"y":"Jesse's home becomes a nonstop party, Skyler reluctantly seeks Saul's help, Marie falls back into an old habit, and Hank is asked to consult on a case.","p":"/assets/stills/breaking-bad-s4e3.jpg"},{"t":"breaking-bad","s":4,"e":4,"n":"Bullet Points","r":46,"y":"Walt and Skyler rehearse a cover story for the family, the cartel moves to gain leverage, and Jesse's behavior attracts unwanted scrutiny.","p":"/assets/stills/breaking-bad-s4e4.jpg"},{"t":"breaking-bad","s":4,"e":5,"n":"Shotgun","r":48,"y":"Walt fears for Jesse when he cannot reach him, Skyler crosses paths with an old acquaintance, and Hank shares grim news with a colleague.","p":"/assets/stills/breaking-bad-s4e5.jpg"},{"t":"breaking-bad","s":4,"e":6,"n":"Cornered","r":48,"y":"Skyler stumbles onto something unsettling, Walter Jr. coaxes his father into a flashy purchase, and Jesse offers Mike a surprising hand.","p":"/assets/stills/breaking-bad-s4e6.jpg"},{"t":"breaking-bad","s":4,"e":7,"n":"Problem Dog","r":48,"y":"A frustrated Walt takes a big gamble, Skyler's car wash venture hits an obstacle, and Hank brings Walter Jr. along on an odd errand.","p":"/assets/stills/breaking-bad-s4e7.jpg"},{"t":"breaking-bad","s":4,"e":8,"n":"Hermanos","r":48,"y":"Skyler finds a creative answer to her cash problem, Hank asks Walt to help test a theory, and a look into Gus's past fills in his history.","p":"/assets/stills/breaking-bad-s4e8.jpg"},{"t":"breaking-bad","s":4,"e":9,"n":"Bug","r":48,"y":"Mistakes from Skyler's past resurface, Gus counters moves by his cartel rivals, and Jesse turns to Walt for help in a tense situation.","p":"/assets/stills/breaking-bad-s4e9.jpg"},{"t":"breaking-bad","s":4,"e":10,"n":"Salud","r":48,"y":"Walt misses his son's sixteenth birthday, worrying the family, while Jesse travels to Mexico and must prove his cooking skills without his mentor.","p":"/assets/stills/breaking-bad-s4e10.jpg"},{"t":"breaking-bad","s":4,"e":11,"n":"Crawl Space","r":47,"y":"Walt takes bold steps to guard his secret and his family, while Skyler's attempt to fix Ted's money troubles runs into resistance.","p":"/assets/stills/breaking-bad-s4e11.jpg"},{"t":"breaking-bad","s":4,"e":12,"n":"End Times","r":46,"y":"Hank urges Gomez to chase one final lead as Walt tries to keep his family safe, and Jesse receives alarming news that sends him to Walt.","p":"/assets/stills/breaking-bad-s4e12.jpg"},{"t":"breaking-bad","s":4,"e":13,"n":"Face Off","r":51,"y":"Walt and Jesse join forces against Gus, and with Saul's assistance, Walt finds help from an unexpected quarter.","p":"/assets/stills/breaking-bad-s4e13.jpg"},{"t":"breaking-bad","s":5,"e":1,"n":"Live Free or Die","r":43,"y":"Walt confronts the loose ends left behind by recent events, while Hank works to close out his investigation into Gus's empire.","p":"/assets/stills/breaking-bad-s5e1.jpg"},{"t":"breaking-bad","s":5,"e":2,"n":"Madrigal","r":48,"y":"Walt and Jesse look for a new business partner as investigators across borders comb through leads tied to a multinational company.","p":"/assets/stills/breaking-bad-s5e2.jpg"},{"t":"breaking-bad","s":5,"e":3,"n":"Hazard Pay","r":48,"y":"The partners draw up a new plan for their operation, including recruiting a crew, while Walt confides something surprising to Marie.","p":"/assets/stills/breaking-bad-s5e3.jpg"},{"t":"breaking-bad","s":5,"e":4,"n":"Fifty-One","r":48,"y":"Walt marks his fifty-first birthday as Skyler weighs her options and a colleague throws a complication into the partners' plans.","p":"/assets/stills/breaking-bad-s5e4.jpg"},{"t":"breaking-bad","s":5,"e":5,"n":"Dead Freight","r":49,"y":"Walt's team devises an audacious plan to obtain the precursor chemical they need to keep their operation running.","p":"/assets/stills/breaking-bad-s5e5.jpg"},{"t":"breaking-bad","s":5,"e":6,"n":"Buyout","r":48,"y":"Walt, Jesse, and Mike clash over the future of the enterprise as a disturbing incident weighs heavily on Jesse's conscience.","p":"/assets/stills/breaking-bad-s5e6.jpg"},{"t":"breaking-bad","s":5,"e":7,"n":"Say My Name","r":48,"y":"Walt takes firm control of the business while Mike contends with the consequences of his own choices.","p":"/assets/stills/breaking-bad-s5e7.jpg"},{"t":"breaking-bad","s":5,"e":8,"n":"Gliding Over All","r":48,"y":"Walt sets out to tie up loose ends in his operation and makes a risky decision about the future.","p":"/assets/stills/breaking-bad-s5e8.jpg"},{"t":"breaking-bad","s":5,"e":9,"n":"Blood Money","r":48,"y":"While Walt and Jesse try to adjust to life away from the business, Hank grapples with a troubling lead he cannot ignore.","p":"/assets/stills/breaking-bad-s5e9.jpg"},{"t":"breaking-bad","s":5,"e":10,"n":"Buried","r":48,"y":"Skyler faces pressure from her past as Walt works to cover his tracks and Jesse continues to wrestle with overwhelming guilt.","p":"/assets/stills/breaking-bad-s5e10.jpg"},{"t":"breaking-bad","s":5,"e":11,"n":"Confessions","r":48,"y":"Jesse resolves to make a change in his life, while Walt and Skyler respond to an unexpected demand that threatens them.","p":"/assets/stills/breaking-bad-s5e11.jpg"},{"t":"breaking-bad","s":5,"e":12,"n":"Rabid Dog","r":48,"y":"An unconventional strategy begins to pay off, and plans are set in motion that could transform everything for the people involved.","p":"/assets/stills/breaking-bad-s5e12.jpg"},{"t":"breaking-bad","s":5,"e":13,"n":"To'hajiilee","r":47,"y":"Walt finds the pressure mounting from unexpected directions as several plans converge in the New Mexico desert.","p":"/assets/stills/breaking-bad-s5e13.jpg"},{"t":"breaking-bad","s":5,"e":14,"n":"Ozymandias","r":48,"y":"The characters are forced to reckon with dramatically altered circumstances in the aftermath of a pivotal confrontation.","p":"/assets/stills/breaking-bad-s5e14.jpg"},{"t":"breaking-bad","s":5,"e":15,"n":"Granite State","r":54,"y":"Living in a very different world than before, Walt and those around him face the slow approach of long-brewing consequences.","p":"/assets/stills/breaking-bad-s5e15.jpg"},{"t":"breaking-bad","s":5,"e":16,"n":"Felina","r":56,"y":"The series concludes as Walt sets out to settle his affairs once and for all.","p":"/assets/stills/breaking-bad-s5e16.jpg"},{"t":"succession","s":1,"e":1,"n":"Celebration","r":62,"y":"On his eightieth birthday, media titan Logan Roy surprises his children by staying on as CEO, upending Kendall's expectations while he juggles a tricky acquisition.","p":"/assets/stills/succession-s1e1.jpg"},{"t":"succession","s":1,"e":2,"n":"Sh*t Show at the F**k Factory","r":59,"y":"A medical emergency throws Logan's empire into turmoil, sparking a bitter debate among his children and board over who should lead Waystar Royco.","p":"/assets/stills/succession-s1e2.jpg"},{"t":"succession","s":1,"e":3,"n":"Lifeboats","r":58,"y":"As the company's share price tumbles, Kendall uncovers a hidden financial crisis, Shiv looks into Logan's wife Marcia, and the siblings step into new roles.","p":"/assets/stills/succession-s1e3.jpg"},{"t":"succession","s":1,"e":4,"n":"Sad Sack Wasp Trap","r":58,"y":"With Logan sidelined, Kendall preps for the company's charity gala, Shiv handles a scandal threatening a client, and Tom inherits a troublesome situation at the cruise division.","p":"/assets/stills/succession-s1e4.jpg"},{"t":"succession","s":1,"e":5,"n":"I Went to Market","r":56,"y":"Kendall starts organizing a board revolt against his father, while Greg chauffeurs his cantankerous grandfather to a tense family Thanksgiving with Logan.","p":"/assets/stills/succession-s1e5.jpg"},{"t":"succession","s":1,"e":6,"n":"Which Side Are You On?","r":58,"y":"Ahead of the decisive board vote, Kendall and Roman scramble for support while Logan travels to Washington hoping to meet the president.","p":"/assets/stills/succession-s1e6.jpg"},{"t":"succession","s":1,"e":7,"n":"Austerlitz","r":58,"y":"Logan agrees to a family therapy weekend at Connor's New Mexico ranch, hoping to stage a public relations win, as Kendall finds his sobriety tested.","p":"/assets/stills/succession-s1e7.jpg"},{"t":"succession","s":1,"e":8,"n":"Prague","r":56,"y":"Tom's bachelor party in Prague gets wild, Kendall eyes an outside investment, Roman chases a local TV deal, and Shiv faces an ambush interview.","p":"/assets/stills/succession-s1e8.jpg"},{"t":"succession","s":1,"e":9,"n":"Pre-Nuptial","r":58,"y":"The Roys gather at an English castle for Shiv and Tom's wedding, reuniting with their sharp-tongued mother as Kendall's secret plan accelerates.","p":"/assets/stills/succession-s1e9.jpg"},{"t":"succession","s":1,"e":10,"n":"Nobody Is Ever Missing","r":66,"y":"During the festivities of Shiv and Tom's wedding, news of a takeover bid spreads, putting Logan on the defensive as Kendall seeks a release.","p":"/assets/stills/succession-s1e10.jpg"},{"t":"succession","s":2,"e":1,"n":"The Summer Palace","r":59,"y":"Kendall tries to repair things with his father after his failed coup, Logan weighs his banker's advice, and Shiv wonders whether succession talk is sincere.","p":"/assets/stills/succession-s2e1.jpg"},{"t":"succession","s":2,"e":2,"n":"Vaulter","r":58,"y":"Kendall and Roman are dispatched to evaluate a digital media brand, Greg questions his place at ATN, and Connor and Willa throw a party in New York.","p":"/assets/stills/succession-s2e2.jpg"},{"t":"succession","s":2,"e":3,"n":"Hunting","r":59,"y":"Logan unveils a bid for a rival media company at a corporate retreat, Greg worries about a meeting with a biographer, and Connor's ambitions irritate his father.","p":"/assets/stills/succession-s2e3.jpg"},{"t":"succession","s":2,"e":4,"n":"Safe Room","r":58,"y":"Roman starts a management training program, Connor and Willa attend a complicated funeral, and Logan and Kendall meet secretly with a rival CEO.","p":"/assets/stills/succession-s2e4.jpg"},{"t":"succession","s":2,"e":5,"n":"Tern Haven","r":60,"y":"Logan courts the Pierce family at their country home to close a major acquisition, while his children struggle to stay on script for the weekend.","p":"/assets/stills/succession-s2e5.jpg"},{"t":"succession","s":2,"e":6,"n":"Argestes","r":58,"y":"At a media and banking retreat, Logan works to close the Pierce deal while a fresh threat emerges and his children argue about damage control.","p":"/assets/stills/succession-s2e6.jpg"},{"t":"succession","s":2,"e":7,"n":"Return","r":58,"y":"The family travels to the UK, where Roman and Shiv try to negotiate with their mother while Logan and Kendall revisit a painful past episode.","p":"/assets/stills/succession-s2e7.jpg"},{"t":"succession","s":2,"e":8,"n":"Dundee","r":60,"y":"The Roys converge on Dundee, Scotland, to honor Logan's fifty years in business, as Kendall becomes infatuated with an actress from Willa's play.","p":"/assets/stills/succession-s2e8.jpg"},{"t":"succession","s":2,"e":9,"n":"DC","r":61,"y":"Waystar's top brass prepare to testify before Congress in Washington, Shiv reaches out to a potential witness, and Roman's overseas pitch takes a dangerous turn.","p":"/assets/stills/succession-s2e9.jpg"},{"t":"succession","s":2,"e":10,"n":"This Is Not for Tears","r":69,"y":"Aboard the family yacht, Logan considers who must take the fall to protect the company's battered reputation, as Roman questions a new source of money.","p":"/assets/stills/succession-s2e10.jpg"},{"t":"succession","s":3,"e":1,"n":"Secession","r":57,"y":"In the wake of a public bombshell, Kendall hunts for a headquarters and allies, while Logan's inner circle searches for a safe place to regroup.","p":"/assets/stills/succession-s3e1.jpg"},{"t":"succession","s":3,"e":2,"n":"Mass in Time of War","r":59,"y":"Kendall courts his siblings and old allies to join his crusade, while a worried Greg seeks help from his grandfather Ewan amid his legal fears.","p":"/assets/stills/succession-s3e2.jpg"},{"t":"succession","s":3,"e":3,"n":"The Disruption","r":59,"y":"With federal investigators circling, Logan marshals his forces, Tom weighs a weighty sacrifice, and Kendall grows fixated on how he is being portrayed.","p":"/assets/stills/succession-s3e3.jpg"},{"t":"succession","s":3,"e":4,"n":"Lion in the Meadow","r":59,"y":"Logan and Kendall come face to face in a meeting with Josh, a major investor uneasy about their public family feud.","p":"/assets/stills/succession-s3e4.jpg"},{"t":"succession","s":3,"e":5,"n":"Retired Janitors of Idaho","r":60,"y":"Kendall and the Waystar team find themselves working side by side at the annual shareholder meeting, where unexpected complications arise.","p":"/assets/stills/succession-s3e5.jpg"},{"t":"succession","s":3,"e":6,"n":"What It Takes","r":58,"y":"Logan and his team head to a conservative political gathering in Virginia, where the family weighs in on a critical endorsement and Roman hears surprising news.","p":"/assets/stills/succession-s3e6.jpg"},{"t":"succession","s":3,"e":7,"n":"Too Much Birthday","r":58,"y":"Kendall throws an extravagant fortieth birthday party, while Shiv and Roman try to secure a meeting with tech mogul Lukas Matsson.","p":"/assets/stills/succession-s3e7.jpg"},{"t":"succession","s":3,"e":8,"n":"Chiantishire","r":64,"y":"At a lavish family wedding in Tuscany, Roman voices suspicions, Gerri sets a firm boundary, and the Waystar team frets over disruptive tweets.","p":"/assets/stills/succession-s3e8.jpg"},{"t":"succession","s":3,"e":9,"n":"All the Bells Say","r":65,"y":"Matsson's ambitions for a Waystar deal force Shiv and Roman to contain the fallout, while Logan carefully weighs his options at the Italian villa.","p":"/assets/stills/succession-s3e9.jpg"},{"t":"succession","s":4,"e":1,"n":"The Munsters","r":61,"y":"While the siblings refine a startup pitch in Los Angeles, a call from Tom pulls their focus to a coveted company, and Logan celebrates a birthday.","p":"/assets/stills/succession-s4e1.jpg"},{"t":"succession","s":4,"e":2,"n":"Rehearsal","r":59,"y":"Shiv learns Tom is following Logan's lead, prompting the siblings to consider an aggressive move against Matsson, while Connor's rehearsal dinner wobbles without Willa.","p":"/assets/stills/succession-s4e2.jpg"},{"t":"succession","s":4,"e":3,"n":"Connor's Wedding","r":62,"y":"Logan prepares to fly to Europe for a face-to-face meeting with Matsson, while Connor obsesses over details on his wedding day aboard a boat.","p":"/assets/stills/succession-s4e3.jpg"},{"t":"succession","s":4,"e":4,"n":"Honeymoon States","r":60,"y":"The siblings navigate a misstep in dealings with Matsson as the Waystar team weighs a crucial board recommendation ahead of a major sale.","p":"/assets/stills/succession-s4e4.jpg"},{"t":"succession","s":4,"e":5,"n":"Kill List","r":61,"y":"Waystar's veteran executives head to Norway for a GoJo team retreat, uneasy about its real purpose, as the siblings ponder whether to fight for ATN.","p":"/assets/stills/succession-s4e5.jpg"},{"t":"succession","s":4,"e":6,"n":"Living+","r":63,"y":"Ahead of a big product launch at Investor Day, Shiv weighs an offer from Matsson while Kendall and Roman attempt to channel their father's style.","p":"/assets/stills/succession-s4e6.jpg"},{"t":"succession","s":4,"e":7,"n":"Tailgate Party","r":62,"y":"At the annual election-eve party, the siblings try to angle for leverage on the GoJo deal, while Connor rethinks his campaign after new intel.","p":"/assets/stills/succession-s4e7.jpg"},{"t":"succession","s":4,"e":8,"n":"America Decides","r":66,"y":"On a chaotic election night, Tom tries to run a frantic ATN newsroom while the siblings argue over the stakes of the result for the company and country.","p":"/assets/stills/succession-s4e8.jpg"},{"t":"succession","s":4,"e":9,"n":"Church and State","r":74,"y":"As the family prepares for an emotional funeral, Kendall clashes with Rava and gets untimely news, while Shiv repositions herself in a new political landscape.","p":"/assets/stills/succession-s4e9.jpg"},{"t":"succession","s":4,"e":10,"n":"With Open Eyes","r":89,"y":"Ahead of the final board vote on the GoJo deal, Kendall and Shiv try to shore up their competing interests while tracking down a bruised Roman.","p":"/assets/stills/succession-s4e10.jpg"},{"t":"the-crown","s":1,"e":1,"n":"Wolferton Splash","r":57,"y":"Princess Elizabeth weds Philip Mountbatten as King George VI's health declines and Winston Churchill returns to Downing Street for a second term.","p":"/assets/stills/the-crown-s1e1.jpg"},{"t":"the-crown","s":1,"e":2,"n":"Hyde Park Corner","r":61,"y":"Standing in for her ailing father, Elizabeth sets off with Philip on a lengthy Commonwealth tour while political rivals plot against an aging Churchill.","p":"/assets/stills/the-crown-s1e2.jpg"},{"t":"the-crown","s":1,"e":3,"n":"Windsor","r":59,"y":"Adjusting to life as monarch, Elizabeth faces Philip's push for influence, Churchill's coronation timing, and the arrival of her uncle, the exiled former king.","p":"/assets/stills/the-crown-s1e3.jpg"},{"t":"the-crown","s":1,"e":4,"n":"Act of God","r":58,"y":"A thick, deadly fog smothers London for days, and Churchill's slow response hands his political opponents an opening to challenge him.","p":"/assets/stills/the-crown-s1e4.jpg"},{"t":"the-crown","s":1,"e":5,"n":"Smoke and Mirrors","r":55,"y":"Elizabeth breaks with tradition by putting Philip in charge of coronation planning, sparking friction, as the Duke of Windsor comes back to London.","p":"/assets/stills/the-crown-s1e5.jpg"},{"t":"the-crown","s":1,"e":6,"n":"Gelignite","r":58,"y":"Princess Margaret and Group Captain Peter Townsend approach the Queen with a personal request just as the press prepares to expose their romance.","p":"/assets/stills/the-crown-s1e6.jpg"},{"t":"the-crown","s":1,"e":7,"n":"Scientia Potentia Est","r":59,"y":"With the Soviets testing a hydrogen bomb and Britain's leaders in poor health, Elizabeth hires a tutor to fill gaps in her schooling.","p":"/assets/stills/the-crown-s1e7.jpg"},{"t":"the-crown","s":1,"e":8,"n":"Pride & Joy","r":58,"y":"The Queen and Philip undertake a grueling global tour, leaving Margaret to handle some royal engagements in her own lively style.","p":"/assets/stills/the-crown-s1e8.jpg"},{"t":"the-crown","s":1,"e":9,"n":"Assassins","r":60,"y":"As friction with Philip grows, Elizabeth seeks comfort in an old friendship, while artist Graham Sutherland paints Churchill's portrait for his eightieth birthday.","p":"/assets/stills/the-crown-s1e9.jpg"},{"t":"the-crown","s":1,"e":10,"n":"Gloriana","r":55,"y":"Margaret and Townsend are reunited but encounter fresh obstacles, leaving Elizabeth caught between her constitutional role and her loyalty to her sister.","p":"/assets/stills/the-crown-s1e10.jpg"},{"t":"the-crown","s":2,"e":1,"n":"Misadventure","r":57,"y":"As Philip leaves on a long voyage, Elizabeth stumbles on something troubling, and Prime Minister Eden plots a response after Egypt nationalizes the Suez Canal.","p":"/assets/stills/the-crown-s2e1.jpg"},{"t":"the-crown","s":2,"e":2,"n":"A Company of Men","r":55,"y":"Far from home, Philip feels the pull of a male-only voyage while Elizabeth feels distant from him and Eden buckles under international pressure.","p":"/assets/stills/the-crown-s2e2.jpg"},{"t":"the-crown","s":2,"e":3,"n":"Lisbon","r":56,"y":"Courtiers move to contain a potential scandal touching Philip's circle, while Eden weathers criticism from his cabinet and newspapers over Suez.","p":"/assets/stills/the-crown-s2e3.jpg"},{"t":"the-crown","s":2,"e":4,"n":"Beryl","r":61,"y":"The royal couple celebrates their tenth anniversary as Margaret meets a charismatic photographer and the new prime minister faces romantic troubles of his own.","p":"/assets/stills/the-crown-s2e4.jpg"},{"t":"the-crown","s":2,"e":5,"n":"Marionettes","r":61,"y":"A stiff speech by the Queen at a car factory prompts a young aristocrat to publicly criticize her and the monarchy's outdated image.","p":"/assets/stills/the-crown-s2e5.jpg"},{"t":"the-crown","s":2,"e":6,"n":"Vergangenheit","r":62,"y":"Wartime papers reveal disturbing information about a royal relative, just as the Duke of Windsor lobbies for a return to public duties.","p":"/assets/stills/the-crown-s2e6.jpg"},{"t":"the-crown","s":2,"e":7,"n":"Matrimonium","r":60,"y":"A message from Peter Townsend prompts Margaret to make a bold move, while news from Elizabeth complicates her sister's plans.","p":"/assets/stills/the-crown-s2e7.jpg"},{"t":"the-crown","s":2,"e":8,"n":"Dear Mrs. Kennedy","r":57,"y":"Spurred by a visit from the Kennedys, Elizabeth takes an unconventional approach to keep Ghana within the Commonwealth despite her government's caution.","p":"/assets/stills/the-crown-s2e8.jpg"},{"t":"the-crown","s":2,"e":9,"n":"Paterfamilias","r":60,"y":"Philip insists that Charles attend the rugged Scottish school he once endured, prompting memories of his own difficult youth there.","p":"/assets/stills/the-crown-s2e9.jpg"},{"t":"the-crown","s":2,"e":10,"n":"Mystery Man","r":59,"y":"A government sex scandal edges uncomfortably close to the palace while Elizabeth retreats to Scotland during a difficult pregnancy.","p":"/assets/stills/the-crown-s2e10.jpg"},{"t":"the-crown","s":3,"e":1,"n":"Olding","r":47,"y":"With a new cast, the royal family mourns Winston Churchill as Labour's Harold Wilson becomes prime minister amid rumors of Soviet sympathies.","p":"/assets/stills/the-crown-s3e1.jpg"},{"t":"the-crown","s":3,"e":2,"n":"Margaretology","r":47,"y":"Margaret and Lord Snowdon tour the United States, and the Queen asks her sister to help secure President Johnson's financial support for Britain.","p":"/assets/stills/the-crown-s3e2.jpg"},{"t":"the-crown","s":3,"e":3,"n":"Aberfan","r":55,"y":"After a devastating disaster strikes a Welsh mining village, the Queen hesitates to visit and must examine why she holds back.","p":"/assets/stills/the-crown-s3e3.jpg"},{"t":"the-crown","s":3,"e":4,"n":"Bubbikins","r":59,"y":"After political upheaval in Greece, Philip's unconventional mother Princess Alice comes to live at Buckingham Palace, intriguing a curious journalist.","p":"/assets/stills/the-crown-s3e4.jpg"},{"t":"the-crown","s":3,"e":5,"n":"Coup","r":57,"y":"While the Queen travels to study horse breeding, discontent over a weak pound draws Lord Mountbatten into talk of removing Harold Wilson.","p":"/assets/stills/the-crown-s3e5.jpg"},{"t":"the-crown","s":3,"e":6,"n":"Tywysog Cymru","r":55,"y":"Prince Charles is sent to university in Aberystwyth to learn Welsh from a passionate nationalist before his investiture as Prince of Wales.","p":"/assets/stills/the-crown-s3e6.jpg"},{"t":"the-crown","s":3,"e":7,"n":"Moondust","r":56,"y":"The 1969 moon landing sparks a midlife crisis for Philip, who begins wondering what adventures he gave up as the Queen's consort.","p":"/assets/stills/the-crown-s3e7.jpg"},{"t":"the-crown","s":3,"e":8,"n":"Dangling Man","r":47,"y":"Charles travels to Paris to visit his ailing great-uncle, the Duke of Windsor, as questions linger about whether the Queen will reconcile with him.","p":"/assets/stills/the-crown-s3e8.jpg"},{"t":"the-crown","s":3,"e":9,"n":"Imbroglio","r":47,"y":"Princess Anne dates Andrew Parker Bowles while Charles falls hard for Camilla Shand, prompting the Queen Mother and Mountbatten to intervene.","p":"/assets/stills/the-crown-s3e9.jpg"},{"t":"the-crown","s":3,"e":10,"n":"Cri de Coeur","r":58,"y":"With her marriage collapsing, Margaret finds comfort with a much younger man, as the nation prepares to celebrate the Queen's Silver Jubilee.","p":"/assets/stills/the-crown-s3e10.jpg"},{"t":"the-crown","s":4,"e":1,"n":"Gold Stick","r":54,"y":"Elizabeth welcomes Margaret Thatcher as Britain's first female prime minister and Charles meets a young Diana Spencer, as an IRA threat looms over the family.","p":"/assets/stills/the-crown-s4e1.jpg"},{"t":"the-crown","s":4,"e":2,"n":"The Balmoral Test","r":57,"y":"Thatcher's visit to Balmoral exposes a clash of cultures with the royals, while Charles finds himself pulled between his heart and his duty.","p":"/assets/stills/the-crown-s4e2.jpg"},{"t":"the-crown","s":4,"e":3,"n":"Fairytale","r":56,"y":"Newly engaged, Diana moves into Buckingham Palace and confronts endless protocol training, isolation, and the lingering presence of Camilla.","p":"/assets/stills/the-crown-s4e3.jpg"},{"t":"the-crown","s":4,"e":4,"n":"Favourites","r":60,"y":"Thatcher contends with a worrying family crisis while Elizabeth reflects on her own relationships with each of her four children.","p":"/assets/stills/the-crown-s4e4.jpg"},{"t":"the-crown","s":4,"e":5,"n":"Fagan","r":52,"y":"Amid soaring unemployment under Thatcher, a desperate intruder slips into Buckingham Palace and reaches the Queen's bedroom wanting to talk.","p":"/assets/stills/the-crown-s4e5.jpg"},{"t":"the-crown","s":4,"e":6,"n":"Terra Nullius","r":54,"y":"On a high-profile tour of Australia, Diana tries to balance motherhood and royal duties while she and Charles struggle in their marriage.","p":"/assets/stills/the-crown-s4e6.jpg"},{"t":"the-crown","s":4,"e":7,"n":"The Hereditary Principle","r":50,"y":"Battling depression, Margaret seeks therapy and uncovers a troubling secret about relatives the royal family kept out of view.","p":"/assets/stills/the-crown-s4e7.jpg"},{"t":"the-crown","s":4,"e":8,"n":"48:1","r":53,"y":"As much of the Commonwealth condemns apartheid, the Queen and Thatcher clash over whether Britain should support sanctions on South Africa.","p":"/assets/stills/the-crown-s4e8.jpg"},{"t":"the-crown","s":4,"e":9,"n":"Avalanche","r":49,"y":"A deadly skiing accident in the Swiss Alps prompts Charles and Diana to reconsider their commitment to a struggling marriage.","p":"/assets/stills/the-crown-s4e9.jpg"},{"t":"the-crown","s":4,"e":10,"n":"War","r":54,"y":"Thatcher fights to hold on to power amid a leadership challenge, while Charles grows determined to separate as his marriage frays.","p":"/assets/stills/the-crown-s4e10.jpg"},{"t":"the-crown","s":5,"e":1,"n":"Queen Victoria Syndrome","r":56,"y":"With another new cast, a debate over replacing the royal yacht invites scrutiny of the Queen's reign while Charles and Diana attempt a second honeymoon.","p":"/assets/stills/the-crown-s5e1.jpg"},{"t":"the-crown","s":5,"e":2,"n":"The System","r":50,"y":"Philip supports a grieving relative through her loss, while a tabloid journalist approaches Diana about cooperating on a revealing book.","p":"/assets/stills/the-crown-s5e2.jpg"},{"t":"the-crown","s":5,"e":3,"n":"Mou Mou","r":53,"y":"A young Egyptian street vendor, inspired by the abdicated King Edward, grows into an ambitious businessman determined to break into British high society.","p":"/assets/stills/the-crown-s5e3.jpg"},{"t":"the-crown","s":5,"e":4,"n":"Annus Horribilis","r":54,"y":"Amid a devastating fire at Windsor Castle and troubled marriages among her children, the Queen reflects on forty years on the throne.","p":"/assets/stills/the-crown-s5e4.jpg"},{"t":"the-crown","s":5,"e":5,"n":"The Way Ahead","r":50,"y":"Charles must navigate a public scandal after a private phone call with Camilla becomes public, sending fresh shocks through his marriage.","p":"/assets/stills/the-crown-s5e5.jpg"},{"t":"the-crown","s":5,"e":6,"n":"Ipatiev House","r":59,"y":"Russia's President Yeltsin seeks the Queen's backing for his new democracy, while Elizabeth navigates new strains in her marriage to Philip.","p":"/assets/stills/the-crown-s5e6.jpg"},{"t":"the-crown","s":5,"e":7,"n":"No Woman's Land","r":52,"y":"BBC journalist Martin Bashir pursues an interview with Diana by questionable means, as the lonely princess finds warmth volunteering at a London hospital.","p":"/assets/stills/the-crown-s5e7.jpg"},{"t":"the-crown","s":5,"e":8,"n":"Gunpowder","r":56,"y":"The Queen spends time with Prince William as fireworks on Guy Fawkes Night coincide with the broadcast of Diana's explosive BBC interview.","p":"/assets/stills/the-crown-s5e8.jpg"},{"t":"the-crown","s":5,"e":9,"n":"Couple 31","r":53,"y":"Diana deals with the fallout from her public comments, and the Queen enlists the prime minister's help with a sensitive family matter.","p":"/assets/stills/the-crown-s5e9.jpg"},{"t":"the-crown","s":5,"e":10,"n":"Decommissioned","r":52,"y":"Under intense scrutiny, Charles heads to Hong Kong for the handover and forges a new alliance, while Mohamed Al-Fayed courts a newly divorced Diana.","p":"/assets/stills/the-crown-s5e10.jpg"},{"t":"the-crown","s":6,"e":1,"n":"Persona Non Grata","r":52,"y":"Diana vacations in Saint-Tropez with the Al-Fayed family and grows close to Dodi, while Charles is wounded by the Queen's absence from Camilla's party.","p":"/assets/stills/the-crown-s6e1.jpg"},{"t":"the-crown","s":6,"e":2,"n":"Two Photographs","r":40,"y":"As photographers swarm Diana and Dodi's growing relationship, Charles counters with a carefully staged public outing alongside his sons.","p":"/assets/stills/the-crown-s6e2.jpg"},{"t":"the-crown","s":6,"e":3,"n":"Dis-Moi Oui","r":57,"y":"Dodi's father pushes him toward a proposal while Diana weighs her future, as the couple spends a fateful summer night in Paris.","p":"/assets/stills/the-crown-s6e3.jpg"},{"t":"the-crown","s":6,"e":4,"n":"Aftermath","r":53,"y":"A nation grieves, and the Queen's public silence draws anger and warnings from Charles as she weighs how to respond.","p":"/assets/stills/the-crown-s6e4.jpg"},{"t":"the-crown","s":6,"e":5,"n":"Willsmania","r":53,"y":"Fifteen-year-old William, besieged by the press and adoring fans, searches for stability, and Charles turns to his parents for help.","p":"/assets/stills/the-crown-s6e5.jpg"},{"t":"the-crown","s":6,"e":6,"n":"Ruritania","r":49,"y":"Hoping to modernize the monarchy's image, the Queen turns to Prime Minister Tony Blair, whose advice challenges royal tradition.","p":"/assets/stills/the-crown-s6e6.jpg"},{"t":"the-crown","s":6,"e":7,"n":"Alma Mater","r":50,"y":"Starting university at St Andrews, William notices Kate Middleton, though meddling parents and other prospects complicate any budding romance.","p":"/assets/stills/the-crown-s6e7.jpg"},{"t":"the-crown","s":6,"e":8,"n":"Ritz","r":51,"y":"In declining health, Margaret recalls a wild night out with her sister at the Ritz in 1945 and returns there for her seventieth birthday.","p":"/assets/stills/the-crown-s6e8.jpg"},{"t":"the-crown","s":6,"e":9,"n":"Hope Street","r":53,"y":"Reeling from losses and uneasy about her Golden Jubilee, the Queen bonds with William as he balances an ordinary life with royal expectations.","p":"/assets/stills/the-crown-s6e9.jpg"},{"t":"the-crown","s":6,"e":10,"n":"Sleep, Dearie Sleep","r":73,"y":"The Queen weighs Charles's wish to marry Camilla while planning her own eventual funeral, prompting deep reflection on her life and reign.","p":"/assets/stills/the-crown-s6e10.jpg"},{"t":"normal-people","s":1,"e":1,"n":"Episode 1","r":29,"y":"In a small west of Ireland town, popular athlete Connell and sharp, isolated Marianne begin a hidden connection after school, kept apart from their classmates.","p":"/assets/stills/normal-people-s1e1.jpg"},{"t":"normal-people","s":1,"e":2,"n":"Episode 2","r":28,"y":"Connell and Marianne grow closer in secret, while he dodges friends' questions about his weekends and his mother's job at Marianne's house.","p":"/assets/stills/normal-people-s1e2.jpg"},{"t":"normal-people","s":1,"e":3,"n":"Episode 3","r":33,"y":"As the Debs approaches, Marianne reluctantly helps at a school fundraiser and finds herself out of place among Connell's friends at a club.","p":"/assets/stills/normal-people-s1e3.jpg"},{"t":"normal-people","s":1,"e":4,"n":"Episode 4","r":31,"y":"Months later, Connell begins at Trinity College Dublin, settling into a shared house but struggling to feel at home among affluent, articulate classmates.","p":"/assets/stills/normal-people-s1e4.jpg"},{"t":"normal-people","s":1,"e":5,"n":"Episode 5","r":31,"y":"Connell tries to fit into Marianne's college social circle and offers an apology for the past, as she reconsiders her new relationship.","p":"/assets/stills/normal-people-s1e5.jpg"},{"t":"normal-people","s":1,"e":6,"n":"Episode 6","r":33,"y":"Back together, Connell gains confidence in his studies, yet hesitates to show his feelings for Marianne in front of her friends.","p":"/assets/stills/normal-people-s1e6.jpg"},{"t":"normal-people","s":1,"e":7,"n":"Episode 7","r":27,"y":"Now seeing other people, Marianne and Connell begin to sense how a misunderstanding drove them apart.","p":"/assets/stills/normal-people-s1e7.jpg"},{"t":"normal-people","s":1,"e":8,"n":"Episode 8","r":28,"y":"Connell visits Marianne at her family's summer villa in Italy, where tensions with her boyfriend Jamie are running high.","p":"/assets/stills/normal-people-s1e8.jpg"},{"t":"normal-people","s":1,"e":9,"n":"Episode 9","r":22,"y":"Studying abroad in Sweden, Marianne becomes entangled in a troubling relationship while staying in touch with Connell from afar.","p":"/assets/stills/normal-people-s1e9.jpg"},{"t":"normal-people","s":1,"e":10,"n":"Episode 10","r":26,"y":"Struggling with serious depression after a painful event, Connell leans on Marianne from a distance as he seeks help.","p":"/assets/stills/normal-people-s1e10.jpg"},{"t":"normal-people","s":1,"e":11,"n":"Episode 11","r":28,"y":"Back in Carricklea for the summer, Marianne spends weekends with Connell, and a night out prompts them to talk about what they mean to each other.","p":"/assets/stills/normal-people-s1e11.jpg"},{"t":"normal-people","s":1,"e":12,"n":"Episode 12","r":23,"y":"Settled in Dublin as a couple, Marianne and Connell enjoy a calm stretch until an unexpected opportunity forces them to think about the future.","p":"/assets/stills/normal-people-s1e12.jpg"},{"t":"better-call-saul","s":1,"e":1,"n":"Uno","r":54,"y":"Struggling public defender Jimmy McGill scrapes by on meager fees while caring for his ailing brother, until a chance encounter inspires a risky scheme to land clients.","p":"/assets/stills/better-call-saul-s1e1.jpg"},{"t":"better-call-saul","s":1,"e":2,"n":"Mijo","r":47,"y":"After his plan backfires and lands him in serious danger, Jimmy must talk his way out, while back home his brother's condition requires attention.","p":"/assets/stills/better-call-saul-s1e2.jpg"},{"t":"better-call-saul","s":1,"e":3,"n":"Nacho","r":48,"y":"Jimmy works hard to prove a menacing client is innocent of a crime, putting a strain on his friendship with Kim Wexler.","p":"/assets/stills/better-call-saul-s1e3.jpg"},{"t":"better-call-saul","s":1,"e":4,"n":"Hero","r":47,"y":"Jimmy cooks up a daring publicity stunt to attract new clients, though the move puts pressure on his relationships.","p":"/assets/stills/better-call-saul-s1e4.jpg"},{"t":"better-call-saul","s":1,"e":5,"n":"Alpine Shepherd Boy","r":45,"y":"Bad news interrupts Jimmy's attempts to drum up business and forces him into a tough decision.","p":"/assets/stills/better-call-saul-s1e5.jpg"},{"t":"better-call-saul","s":1,"e":6,"n":"Five-O","r":43,"y":"The past catches up with Mike Ehrmantraut, forcing him to seek help from an unexpected source as Jimmy's sense of right and wrong is tested.","p":"/assets/stills/better-call-saul-s1e6.jpg"},{"t":"better-call-saul","s":1,"e":7,"n":"Bingo","r":48,"y":"Jimmy meets prospective clients and, given a chance to do the right thing, calls in a favor from an unlikely source.","p":"/assets/stills/better-call-saul-s1e7.jpg"},{"t":"better-call-saul","s":1,"e":8,"n":"RICO","r":48,"y":"Jimmy shows his brother Chuck that he is willing to go to great lengths to win a case, even if it gets messy.","p":"/assets/stills/better-call-saul-s1e8.jpg"},{"t":"better-call-saul","s":1,"e":9,"n":"Pimento","r":48,"y":"Chuck presses Jimmy to accept a hard truth, while doubts about Mike's suitability for a job threaten to derail a deal.","p":"/assets/stills/better-call-saul-s1e9.jpg"},{"t":"better-call-saul","s":1,"e":10,"n":"Marco","r":50,"y":"In the wake of recent events, Jimmy seeks comfort by reconnecting with an old friend from his past.","p":"/assets/stills/better-call-saul-s1e10.jpg"},{"t":"better-call-saul","s":2,"e":1,"n":"Switch","r":47,"y":"Jimmy and Kim's relationship takes a new turn as Jimmy weighs a fresh opportunity, while Mike decides to distance himself from a reckless associate.","p":"/assets/stills/better-call-saul-s2e1.jpg"},{"t":"better-call-saul","s":2,"e":2,"n":"Cobbler","r":48,"y":"Mike brokers a deal to keep a potentially messy situation contained, while Jimmy works to help an eccentric client.","p":"/assets/stills/better-call-saul-s2e2.jpg"},{"t":"better-call-saul","s":2,"e":3,"n":"Amarillo","r":43,"y":"Jimmy's efforts to reach new clients flourish with bold showmanship, while Mike puzzles over troubling news from his daughter-in-law Stacey.","p":"/assets/stills/better-call-saul-s2e3.jpg"},{"t":"better-call-saul","s":2,"e":4,"n":"Gloves Off","r":44,"y":"Jimmy's actions create unexpected waves for Kim at work, as Mike cautiously considers a lucrative but risky proposal.","p":"/assets/stills/better-call-saul-s2e4.jpg"},{"t":"better-call-saul","s":2,"e":5,"n":"Rebecca","r":46,"y":"Jimmy chafes against the rules at his new job while Kim works hard to climb out of a deep hole at HHM.","p":"/assets/stills/better-call-saul-s2e5.jpg"},{"t":"better-call-saul","s":2,"e":6,"n":"Bali Ha'i","r":47,"y":"Jimmy finds comfort in old habits, Kim receives an offer that could change her career, and Mike is pushed to his limit by a threat.","p":"/assets/stills/better-call-saul-s2e6.jpg"},{"t":"better-call-saul","s":2,"e":7,"n":"Inflatable","r":43,"y":"Mike's frustration grows when his hand is forced, as Jimmy boldly decides to chart a different course in his career.","p":"/assets/stills/better-call-saul-s2e7.jpg"},{"t":"better-call-saul","s":2,"e":8,"n":"Fifi","r":49,"y":"Mike sets out to settle a score with an enemy, and an unexpected opportunity comes Jimmy's way.","p":"/assets/stills/better-call-saul-s2e8.jpg"},{"t":"better-call-saul","s":2,"e":9,"n":"Nailed","r":50,"y":"Mike takes a careful, methodical approach to his mission, someone questions Chuck's abilities, and Jimmy faces a personal dilemma.","p":"/assets/stills/better-call-saul-s2e9.jpg"},{"t":"better-call-saul","s":2,"e":10,"n":"Klick","r":49,"y":"Jimmy faces a difficult choice, Mike takes matters into his own hands, and Howard Hamlin brings unwelcome news.","p":"/assets/stills/better-call-saul-s2e10.jpg"},{"t":"better-call-saul","s":3,"e":1,"n":"Mabel","r":52,"y":"Tensions between Jimmy and Chuck deepen, Kim feels the pressure of running her own practice, and Mike investigates a mysterious note.","p":"/assets/stills/better-call-saul-s3e1.jpg"},{"t":"better-call-saul","s":3,"e":2,"n":"Witness","r":52,"y":"Jimmy and Kim bring on an assistant, Mike tracks down a mysterious figure, and Chuck uses the law to try to gain the upper hand.","p":"/assets/stills/better-call-saul-s3e2.jpg"},{"t":"better-call-saul","s":3,"e":3,"n":"Sunk Costs","r":46,"y":"Jimmy takes on a new client to Kim's dismay, while Mike meets a formidable figure who makes him a tempting offer.","p":"/assets/stills/better-call-saul-s3e3.jpg"},{"t":"better-call-saul","s":3,"e":4,"n":"Sabrosito","r":48,"y":"Jimmy asks Mike for a favor, fresh complications disrupt the Salamanca family business, and the brothers struggle to reach a compromise.","p":"/assets/stills/better-call-saul-s3e4.jpg"},{"t":"better-call-saul","s":3,"e":5,"n":"Chicanery","r":50,"y":"Kim and Jimmy square off against a formidable adversary in a high-stakes hearing, with Jimmy digging into Chuck's past to protect his future.","p":"/assets/stills/better-call-saul-s3e5.jpg"},{"t":"better-call-saul","s":3,"e":6,"n":"Off Brand","r":48,"y":"Jimmy starts a new venture, Chuck pushes himself to the edge, and Nacho finds himself in a struggle for power.","p":"/assets/stills/better-call-saul-s3e6.jpg"},{"t":"better-call-saul","s":3,"e":7,"n":"Expenses","r":53,"y":"Jimmy works to pay off his debts, Nacho reconnects with an old acquaintance, and Mike helps Stacey with a project.","p":"/assets/stills/better-call-saul-s3e7.jpg"},{"t":"better-call-saul","s":3,"e":8,"n":"Slip","r":49,"y":"Jimmy is pushed toward desperate measures, Nacho learns a new skill, Mike explores a partnership, and Kim stands up to Howard.","p":"/assets/stills/better-call-saul-s3e8.jpg"},{"t":"better-call-saul","s":3,"e":9,"n":"Fall","r":50,"y":"Jimmy reconnects with an old acquaintance and takes up a new hobby, while Chuck and Howard argue over the future of their firm.","p":"/assets/stills/better-call-saul-s3e9.jpg"},{"t":"better-call-saul","s":3,"e":10,"n":"Lantern","r":57,"y":"Kim takes time off, Jimmy tries to make amends, Nacho gambles with his future, and Howard presses Chuck to make a decision.","p":"/assets/stills/better-call-saul-s3e10.jpg"},{"t":"better-call-saul","s":4,"e":1,"n":"Smoke","r":49,"y":"Jimmy struggles to cope with a family loss, Mike considers his role at Madrigal, and Howard makes an unexpected confession.","p":"/assets/stills/better-call-saul-s4e1.jpg"},{"t":"better-call-saul","s":4,"e":2,"n":"Breathe","r":46,"y":"Jimmy looks for new work as Kim tries to support him, while Gus deals with the fallout from a cartel crisis.","p":"/assets/stills/better-call-saul-s4e2.jpg"},{"t":"better-call-saul","s":4,"e":3,"n":"Something Beautiful","r":43,"y":"Jimmy sets a risky plan in motion as shifting alliances put Nacho in danger and Kim considers where her career is heading.","p":"/assets/stills/better-call-saul-s4e3.jpg"},{"t":"better-call-saul","s":4,"e":4,"n":"Talk","r":47,"y":"A restless Jimmy embarks on a new endeavor, Mike burns bridges, Kim pursues work she loves, and Nacho tries to survive a turf war.","p":"/assets/stills/better-call-saul-s4e4.jpg"},{"t":"better-call-saul","s":4,"e":5,"n":"Quite a Ride","r":53,"y":"Jimmy finds a new market for his talents, Mike vets a potential partnership, and Kim drives a hard bargain.","p":"/assets/stills/better-call-saul-s4e5.jpg"},{"t":"better-call-saul","s":4,"e":6,"n":"Piñata","r":48,"y":"While Jimmy dreams of a joint firm with Kim, she makes a bold move of her own, and Mike puts a plan into motion for Gus.","p":"/assets/stills/better-call-saul-s4e6.jpg"},{"t":"better-call-saul","s":4,"e":7,"n":"Something Stupid","r":42,"y":"Jimmy expands his side business but hits a snag only Kim can fix, while Gus takes an interest in Hector's medical care.","p":"/assets/stills/better-call-saul-s4e7.jpg"},{"t":"better-call-saul","s":4,"e":8,"n":"Coushatta","r":53,"y":"Jimmy goes to great lengths to right a wrong as Kim fights hard for a case, while Mike lets his crew blow off steam.","p":"/assets/stills/better-call-saul-s4e8.jpg"},{"t":"better-call-saul","s":4,"e":9,"n":"Wiedersehen","r":55,"y":"Jimmy and Kim open up to each other at the risk of their relationship, while Nacho makes the rounds with Lalo and Mike has cause for concern.","p":"/assets/stills/better-call-saul-s4e9.jpg"},{"t":"better-call-saul","s":4,"e":10,"n":"Winner","r":61,"y":"Jimmy works to turn his reputation around, Lalo chases a loose end in Gus's operation, and Mike faces a difficult decision.","p":"/assets/stills/better-call-saul-s4e10.jpg"},{"t":"better-call-saul","s":5,"e":1,"n":"Magic Man","r":55,"y":"Now operating as Saul Goodman, Jimmy launches an unorthodox client strategy that tests Kim's patience, while Lalo searches for a mysterious man named Michael.","p":"/assets/stills/better-call-saul-s5e1.jpg"},{"t":"better-call-saul","s":5,"e":2,"n":"50% Off","r":46,"y":"Jimmy's promotional stunt has unintended consequences, Nacho goes to extremes to win Lalo's trust, and a troubled Mike loses his temper.","p":"/assets/stills/better-call-saul-s5e2.jpg"},{"t":"better-call-saul","s":5,"e":3,"n":"The Guy for This","r":55,"y":"Jimmy's business moves into unfamiliar territory, Kim's confidence is tested by a legal problem, and Nacho faces mounting pressure from Gus.","p":"/assets/stills/better-call-saul-s5e3.jpg"},{"t":"better-call-saul","s":5,"e":4,"n":"Namaste","r":47,"y":"As Jimmy fully commits to his Saul Goodman persona, a conflicted Kim brings him a proposition, and Mike tries to repair things with his family.","p":"/assets/stills/better-call-saul-s5e4.jpg"},{"t":"better-call-saul","s":5,"e":5,"n":"Dedicado a Max","r":51,"y":"Mike takes an unexpected trip out of town, while Kim and Jimmy grow closer working together to help a client.","p":"/assets/stills/better-call-saul-s5e5.jpg"},{"t":"better-call-saul","s":5,"e":6,"n":"Wexler v. Goodman","r":52,"y":"Kim tries to slow down Jimmy's latest scheme, but Saul may be unstoppable, as Mike turns up the pressure on Lalo.","p":"/assets/stills/better-call-saul-s5e6.jpg"},{"t":"better-call-saul","s":5,"e":7,"n":"JMM","r":48,"y":"Jimmy and Kim set up legal safeguards with help from Huell, while Gus works to calm tensions in service of his long-term plans.","p":"/assets/stills/better-call-saul-s5e7.jpg"},{"t":"better-call-saul","s":5,"e":8,"n":"Bagman","r":55,"y":"A seemingly simple errand for a client sends Jimmy on a grueling journey through the desert, as Mike works to contain the cartel's anger.","p":"/assets/stills/better-call-saul-s5e8.jpg"},{"t":"better-call-saul","s":5,"e":9,"n":"Bad Choice Road","r":60,"y":"Shaken by Jimmy's harrowing ordeal, Kim reassesses what matters most, while Jimmy struggles to get back to business as usual.","p":"/assets/stills/better-call-saul-s5e9.jpg"},{"t":"better-call-saul","s":5,"e":10,"n":"Something Unforgivable","r":61,"y":"Jimmy and Kim pursue an ill-advised plan that takes a serious turn, while Nacho is drawn closer to the cartel than he would like.","p":"/assets/stills/better-call-saul-s5e10.jpg"},{"t":"better-call-saul","s":6,"e":1,"n":"Wine and Roses","r":56,"y":"Nacho runs for his life, Jimmy and Kim hatch a scheme, and Mike questions where his loyalties should lie.","p":"/assets/stills/better-call-saul-s6e1.jpg"},{"t":"better-call-saul","s":6,"e":2,"n":"Carrot and Stick","r":60,"y":"Nacho confronts harsh realities while hiding out, and Gus investigates his suspicions about recent events.","p":"/assets/stills/better-call-saul-s6e2.jpg"},{"t":"better-call-saul","s":6,"e":3,"n":"Rock and Hard Place","r":47,"y":"Still on the run, Nacho is forced to choose where his loyalties lie, while Jimmy doubles down on his plans.","p":"/assets/stills/better-call-saul-s6e3.jpg"},{"t":"better-call-saul","s":6,"e":4,"n":"Hit and Run","r":45,"y":"Gus takes extreme precautions, while Jimmy and Kim recruit a local performer to stage an elaborate show.","p":"/assets/stills/better-call-saul-s6e4.jpg"},{"t":"better-call-saul","s":6,"e":5,"n":"Black and Blue","r":52,"y":"As Jimmy's business booms, the cat-and-mouse game between Gus and Lalo grows tighter.","p":"/assets/stills/better-call-saul-s6e5.jpg"},{"t":"better-call-saul","s":6,"e":6,"n":"Axe and Grind","r":45,"y":"Kim and Jimmy turn to a knowledgeable contact for help, while Howard starts looking closely into Jimmy's business practices.","p":"/assets/stills/better-call-saul-s6e6.jpg"},{"t":"better-call-saul","s":6,"e":7,"n":"Plan and Execution","r":51,"y":"Jimmy and Kim scramble to handle a last-minute problem with their plan as Howard's investigation begins to pay off.","p":"/assets/stills/better-call-saul-s6e7.jpg"},{"t":"better-call-saul","s":6,"e":8,"n":"Point and Shoot","r":50,"y":"An unexpected visitor forces Jimmy and Kim to face the consequences of their choices.","p":"/assets/stills/better-call-saul-s6e8.jpg"},{"t":"better-call-saul","s":6,"e":9,"n":"Fun and Games","r":57,"y":"Gus works to smooth relations with the cartel, while Mike tidies up remaining loose ends.","p":"/assets/stills/better-call-saul-s6e9.jpg"},{"t":"better-call-saul","s":6,"e":10,"n":"Nippy","r":52,"y":"Living under a new identity, a man befriends a woman over a lost dog, and a new scheme begins to take shape.","p":"/assets/stills/better-call-saul-s6e10.jpg"},{"t":"better-call-saul","s":6,"e":11,"n":"Breaking Bad","r":58,"y":"A glimpse into Saul Goodman's past sheds light on familiar faces, as partners in crime decide to push their enterprise further.","p":"/assets/stills/better-call-saul-s6e11.jpg"},{"t":"better-call-saul","s":6,"e":12,"n":"Waterworks","r":59,"y":"The stakes rise for Gene when a discovery threatens to send ripples far and wide.","p":"/assets/stills/better-call-saul-s6e12.jpg"},{"t":"better-call-saul","s":6,"e":13,"n":"Saul Gone","r":70,"y":"In the series finale, Jimmy's past and present collide as he faces a reckoning that brings his many identities together.","p":"/assets/stills/better-call-saul-s6e13.jpg"},{"t":"mad-men","s":1,"e":1,"n":"Smoke Gets in Your Eyes","r":49,"y":"New York, 1960: star creative director Don Draper hunts for a cigarette campaign angle while juggling a demanding client, a new secretary, and an ambitious junior executive.","p":"/assets/stills/mad-men-s1e1.jpg"},{"t":"mad-men","s":1,"e":2,"n":"Ladies Room","r":47,"y":"Don guards the secrets of his private life despite Roger's prodding, and new secretary Peggy navigates unwanted attention from the office men while Pete is away.","p":"/assets/stills/mad-men-s1e2.jpg"},{"t":"mad-men","s":1,"e":3,"n":"Marriage of Figaro","r":44,"y":"Back from his honeymoon, Pete wrestles with what happened with Peggy, while a suburban birthday party leaves Don feeling increasingly restless at home.","p":"/assets/stills/mad-men-s1e3.jpg"},{"t":"mad-men","s":1,"e":4,"n":"New Amsterdam","r":45,"y":"Pressured by his wife to buy a pricey apartment, Pete tries to flex his influence at work and his family name, putting his standing with Don at risk.","p":"/assets/stills/mad-men-s1e4.jpg"},{"t":"mad-men","s":1,"e":5,"n":"5G","r":48,"y":"A trade magazine photo of Don draws an unexpected visitor from his past, while Ken's published short story stirs envy among the junior account men.","p":"/assets/stills/mad-men-s1e5.jpg"},{"t":"mad-men","s":1,"e":6,"n":"Babylon","r":47,"y":"A brainstorm for a lipstick client gives Peggy a chance to show talent beyond typing, while Don seeks Rachel's insight on an Israeli tourism account.","p":"/assets/stills/mad-men-s1e6.jpg"},{"t":"mad-men","s":1,"e":7,"n":"Red in the Face","r":47,"y":"A boozy night out between Roger and Don ends in friction that leads to some pointed retaliation, while Pete keeps struggling with his marriage and his job.","p":"/assets/stills/mad-men-s1e7.jpg"},{"t":"mad-men","s":1,"e":8,"n":"The Hobo Code","r":48,"y":"Peggy's growing confidence complicates things with Pete, Don revisits memories from his childhood, and art director Sal finds himself drawn to a client.","p":"/assets/stills/mad-men-s1e8.jpg"},{"t":"mad-men","s":1,"e":9,"n":"Shoot","r":48,"y":"A competing agency tries to lure Don away by dangling a modeling job in front of Betty, while Sterling Cooper scrambles to answer Kennedy's campaign ads.","p":"/assets/stills/mad-men-s1e9.jpg"},{"t":"mad-men","s":1,"e":10,"n":"Long Weekend","r":48,"y":"Losing an account sours Don's mood until Roger, stuck in Manhattan over Labor Day, tries to lift his spirits; Joan enjoys a night out with her roommate.","p":"/assets/stills/mad-men-s1e10.jpg"},{"t":"mad-men","s":1,"e":11,"n":"Indian Summer","r":48,"y":"Peggy takes on a tricky product assignment, Roger's troubles open doors for Don, Pete's frustration grows, and Betty finds an unusual outlet for her restlessness.","p":"/assets/stills/mad-men-s1e11.jpg"},{"t":"mad-men","s":1,"e":12,"n":"Nixon vs. Kennedy","r":48,"y":"Staffers throw a raucous election-night party as the 1960 returns come in, while Pete pushes a confrontation with Don and Don recalls his time in Korea.","p":"/assets/stills/mad-men-s1e12.jpg"},{"t":"mad-men","s":1,"e":13,"n":"The Wheel","r":49,"y":"As Thanksgiving nears, Don prepares a crucial pitch for Kodak's new slide projector while work keeps pulling him away from family plans.","p":"/assets/stills/mad-men-s1e13.jpg"},{"t":"mad-men","s":2,"e":1,"n":"For Those Who Think Young","r":49,"y":"On Valentine's Day 1962, the agency adjusts to a new photocopier and a push for younger talent, while Don and Duck clash over strategy.","p":"/assets/stills/mad-men-s2e1.jpg"},{"t":"mad-men","s":2,"e":2,"n":"Flight 1","r":49,"y":"Paul introduces his girlfriend at a party, Peggy faces her family over dinner, and the agency chases an airline client despite a possible conflict of interest.","p":"/assets/stills/mad-men-s2e2.jpg"},{"t":"mad-men","s":2,"e":3,"n":"The Benefactor","r":47,"y":"A temperamental comedian disrupts a commercial shoot, Harry backs a controversial TV sponsorship, and Don and Betty host a client dinner to smooth things over.","p":"/assets/stills/mad-men-s2e3.jpg"},{"t":"mad-men","s":2,"e":4,"n":"Three Sundays","r":48,"y":"Across three consecutive Sundays, Peggy's family welcomes a new parish priest, Don and Betty spend a weekend together, and the office prepares a last-minute pitch.","p":"/assets/stills/mad-men-s2e4.jpg"},{"t":"mad-men","s":2,"e":5,"n":"The New Girl","r":49,"y":"Don handles a messy situation involving a TV comic and his wife, while Joan searches for a secretary who will suit Don perfectly.","p":"/assets/stills/mad-men-s2e5.jpg"},{"t":"mad-men","s":2,"e":6,"n":"Maidenform","r":48,"y":"Don and Duck attempt a truce, Peggy tries to break into the men's after-hours gatherings, and Duck receives an uncomfortable visit from his family.","p":"/assets/stills/mad-men-s2e6.jpg"},{"t":"mad-men","s":2,"e":7,"n":"The Gold Violin","r":48,"y":"Don treats himself to a new Cadillac, the junior account men plot ways to win business, and Cooper unveils a striking new painting in his office.","p":"/assets/stills/mad-men-s2e7.jpg"},{"t":"mad-men","s":2,"e":8,"n":"A Night to Remember","r":49,"y":"Peggy lends her skills to a church event, Don and Duck look for ways to sell an imported beer, and Harry seeks help with his television workload.","p":"/assets/stills/mad-men-s2e8.jpg"},{"t":"mad-men","s":2,"e":9,"n":"Six Month Leave","r":49,"y":"A colleague's drinking derails an important pitch, Pete sees an opening to advance, Don stands by an old friend, and Betty finds solace in a new acquaintance.","p":"/assets/stills/mad-men-s2e9.jpg"},{"t":"mad-men","s":2,"e":10,"n":"The Inheritance","r":48,"y":"Betty travels to see her ailing father, Paul's girlfriend pushes him to take on civil rights work, and Pete's mother frowns on his and Trudy's plans.","p":"/assets/stills/mad-men-s2e10.jpg"},{"t":"mad-men","s":2,"e":11,"n":"The Jet Set","r":48,"y":"A business trip to Los Angeles introduces Don to a glamorous group of travelers, while Peggy seeks romance and Duck considers the agency's future.","p":"/assets/stills/mad-men-s2e11.jpg"},{"t":"mad-men","s":2,"e":12,"n":"The Mountain King","r":48,"y":"Don reconnects with someone from his past in California, Pete's home life throws up obstacles, and Joan brings her fiancé by the office.","p":"/assets/stills/mad-men-s2e12.jpg"},{"t":"mad-men","s":2,"e":13,"n":"Meditations in an Emergency","r":48,"y":"With the Cuban Missile Crisis on the news, the office tries to operate without Don, and Betty receives unsettling personal news.","p":"/assets/stills/mad-men-s2e13.jpg"},{"t":"mad-men","s":3,"e":1,"n":"Out of Town","r":48,"y":"In 1963, Don and Sal take a business trip to Baltimore while Pete and Ken anxiously watch the British owners reshuffle Sterling Cooper.","p":"/assets/stills/mad-men-s3e1.jpg"},{"t":"mad-men","s":3,"e":2,"n":"Love Among the Ruins","r":48,"y":"Betty's father comes to stay with the Drapers, Peggy pours herself into a campaign, the firm weighs an odd client request, and Roger plans a wedding.","p":"/assets/stills/mad-men-s3e2.jpg"},{"t":"mad-men","s":3,"e":3,"n":"My Old Kentucky Home","r":48,"y":"Copywriters stuck working late look for ways to pass the night, Roger hosts a lavish Derby party, and Joan and Greg throw a gathering of their own.","p":"/assets/stills/mad-men-s3e3.jpg"},{"t":"mad-men","s":3,"e":4,"n":"The Arrangements","r":48,"y":"Don clashes with his father-in-law, Peggy looks for a new roommate, and a wealthy young heir is eager to fund an unusual campaign.","p":"/assets/stills/mad-men-s3e4.jpg"},{"t":"mad-men","s":3,"e":5,"n":"The Fog","r":48,"y":"Don and Betty are summoned to school over Sally's behavior, Betty has a vivid dream, and Pete tries a fresh approach to winning new business.","p":"/assets/stills/mad-men-s3e5.jpg"},{"t":"mad-men","s":3,"e":6,"n":"Guy Walks Into an Advertising Agency","r":48,"y":"Executives from the British parent company arrive with announcements, a houseguest leaves Sally frightened, and Joan's plans take an unexpected turn.","p":"/assets/stills/mad-men-s3e6.jpg"},{"t":"mad-men","s":3,"e":7,"n":"Seven Twenty Three","r":48,"y":"Betty gets involved in a local political cause, Don is pressed to commit to the agency's future, and Peggy receives an extravagant gift.","p":"/assets/stills/mad-men-s3e7.jpg"},{"t":"mad-men","s":3,"e":8,"n":"Souvenir","r":48,"y":"Don invites Betty along on a business trip to Rome, while Pete offers a neighbor in his building some help that goes too far.","p":"/assets/stills/mad-men-s3e8.jpg"},{"t":"mad-men","s":3,"e":9,"n":"Wee Small Hours","r":48,"y":"A demanding client strains Don and Sal, Don pursues his connection with Sally's teacher, and Betty hosts a political fundraiser at the house.","p":"/assets/stills/mad-men-s3e9.jpg"},{"t":"mad-men","s":3,"e":10,"n":"The Color Blue","r":48,"y":"Sterling Cooper prepares to mark its anniversary, while Peggy and Paul find themselves vying for the same idea on an account.","p":"/assets/stills/mad-men-s3e10.jpg"},{"t":"mad-men","s":3,"e":11,"n":"The Gypsy and the Hobo","r":48,"y":"A familiar client resurfaces, Betty takes the children on a trip, and Joan and Greg make plans for what comes next in their lives.","p":"/assets/stills/mad-men-s3e11.jpg"},{"t":"mad-men","s":3,"e":12,"n":"The Grown-Ups","r":47,"y":"Peggy's romantic choices raise eyebrows, Pete weighs a key career move, and the events of November 1963 bring the office to a standstill.","p":"/assets/stills/mad-men-s3e12.jpg"},{"t":"mad-men","s":3,"e":13,"n":"Shut the Door. Have a Seat","r":48,"y":"Don sits down with Conrad Hilton about their working relationship, Betty takes some advice to heart, and Pete holds a tense meeting with clients.","p":"/assets/stills/mad-men-s3e13.jpg"},{"t":"mad-men","s":4,"e":1,"n":"Public Relations","r":48,"y":"In late 1964, Don bristles at a magazine profile, a bathing-suit maker wants a campaign that stays wholesome, and Pete and Peggy hunt for revenue.","p":"/assets/stills/mad-men-s4e1.jpg"},{"t":"mad-men","s":4,"e":2,"n":"Christmas Comes But Once a Year","r":48,"y":"The new agency's Christmas party draws an unexpected guest who complicates the festivities, while Don spends the holiday season alone.","p":"/assets/stills/mad-men-s4e2.jpg"},{"t":"mad-men","s":4,"e":3,"n":"The Good News","r":48,"y":"Don travels to California over New Year's, Joan juggles a scheduling dilemma, and Don and Lane end up spending an unlikely evening together.","p":"/assets/stills/mad-men-s4e3.jpg"},{"t":"mad-men","s":4,"e":4,"n":"The Rejected","r":48,"y":"A directive from Roger and Lane puts Pete in an awkward bind involving his family, while Peggy ventures into a new downtown social scene.","p":"/assets/stills/mad-men-s4e4.jpg"},{"t":"mad-men","s":4,"e":5,"n":"The Chrysanthemum and the Sword","r":48,"y":"Don and Pete go behind Roger's back in pursuit of a Japanese motorcycle client, setting up a contest with rival agencies.","p":"/assets/stills/mad-men-s4e5.jpg"},{"t":"mad-men","s":4,"e":6,"n":"Waldorf Stories","r":48,"y":"Peggy butts heads with her new creative partner, and Don attends an advertising awards ceremony before pitching under unusual circumstances.","p":"/assets/stills/mad-men-s4e6.jpg"},{"t":"mad-men","s":4,"e":7,"n":"The Suitcase","r":48,"y":"On the night of a famous boxing match, a looming deadline keeps Don and Peggy at the office late, testing their working relationship.","p":"/assets/stills/mad-men-s4e7.jpg"},{"t":"mad-men","s":4,"e":8,"n":"The Summer Man","r":48,"y":"Don takes stock of his life as summer arrives, while Joan and Peggy each handle behavior from the men in the office in their own way.","p":"/assets/stills/mad-men-s4e8.jpg"},{"t":"mad-men","s":4,"e":9,"n":"The Beautiful Girls","r":47,"y":"Peggy confronts a client's discriminatory policies, Don's relationship with Faye is tested when Sally shows up at the office, and Roger reaches out to Joan.","p":"/assets/stills/mad-men-s4e9.jpg"},{"t":"mad-men","s":4,"e":10,"n":"Hands and Knees","r":48,"y":"An unannounced visitor to the Francis home unsettles Betty and Don, while several partners face personal crises they must keep quiet.","p":"/assets/stills/mad-men-s4e10.jpg"},{"t":"mad-men","s":4,"e":11,"n":"Chinese Wall","r":48,"y":"Rumors sweep through Sterling Cooper Draper Pryce after the partners call an all-hands meeting, leaving employees anxious about their jobs.","p":"/assets/stills/mad-men-s4e11.jpg"},{"t":"mad-men","s":4,"e":12,"n":"Blowing Smoke","r":48,"y":"As the agency faces a crisis, Don runs into an old acquaintance and starts rethinking how the firm presents itself.","p":"/assets/stills/mad-men-s4e12.jpg"},{"t":"mad-men","s":4,"e":13,"n":"Tomorrowland","r":48,"y":"Don takes a trip to California with his children, and both he and Peggy find themselves facing decisions that could reshape their lives.","p":"/assets/stills/mad-men-s4e13.jpg"},{"t":"mad-men","s":5,"e":1,"n":"A Little Kiss (1)","r":48,"y":"In 1966, Megan plans a surprise party for Don's birthday, and Joan, now a new mother, wonders whether her job still awaits her.","p":"/assets/stills/mad-men-s5e1.jpg"},{"t":"mad-men","s":5,"e":2,"n":"A Little Kiss (2)","r":47,"y":"Don and Megan sort through some friction after the party, Roger and Pete spar over office space, and Joan deals with a difficult houseguest.","p":"/assets/stills/mad-men-s5e2.jpg"},{"t":"mad-men","s":5,"e":3,"n":"Tea Leaves","r":48,"y":"The agency hunts for new business and Peggy steps into a bigger role, while Don and Harry chase a client backstage and Betty faces a medical worry.","p":"/assets/stills/mad-men-s5e3.jpg"},{"t":"mad-men","s":5,"e":4,"n":"Mystery Date","r":48,"y":"Don has an unexpected encounter with a figure from his past while sick, Roger dumps more work on Peggy, and Joan makes a major personal decision.","p":"/assets/stills/mad-men-s5e4.jpg"},{"t":"mad-men","s":5,"e":5,"n":"Signal 30","r":48,"y":"Lane chases a Jaguar connection and ends up in conflict with Pete, while Pete and Trudy host a dinner party in the suburbs.","p":"/assets/stills/mad-men-s5e5.jpg"},{"t":"mad-men","s":5,"e":6,"n":"Far Away Places","r":48,"y":"Peggy struggles through a tough pitch, Don whisks Megan to a Howard Johnson's upstate, and Roger and Jane try LSD at a dinner party.","p":"/assets/stills/mad-men-s5e6.jpg"},{"t":"mad-men","s":5,"e":7,"n":"At the Codfish Ball","r":48,"y":"Don is honored at an American Cancer Society dinner, Sally helps out a relative, and Megan's parents arrive from Montreal for a visit.","p":"/assets/stills/mad-men-s5e7.jpg"},{"t":"mad-men","s":5,"e":8,"n":"Lady Lazarus","r":48,"y":"Megan reconsiders her future at the agency, Peggy is put in an uncomfortable spot, and Pete's attempt to help an acquaintance takes an unexpected turn.","p":"/assets/stills/mad-men-s5e8.jpg"},{"t":"mad-men","s":5,"e":9,"n":"Dark Shadows","r":48,"y":"Don tries to rekindle his creative spark and competes with a junior copywriter, while Roger courts a new client and Betty stirs up trouble for Sally.","p":"/assets/stills/mad-men-s5e9.jpg"},{"t":"mad-men","s":5,"e":10,"n":"Christmas Waltz","r":48,"y":"Harry reconnects with an old colleague who has joined the Hare Krishnas, Lane faces money troubles, and Don spends an afternoon with Joan.","p":"/assets/stills/mad-men-s5e10.jpg"},{"t":"mad-men","s":5,"e":11,"n":"The Other Woman","r":48,"y":"Pete presents Joan with a troubling proposal tied to the Jaguar pitch, Don chafes at Megan's career plans, and Peggy weighs her worth at the agency.","p":"/assets/stills/mad-men-s5e11.jpg"},{"t":"mad-men","s":5,"e":12,"n":"Commissions and Fees","r":48,"y":"Lane faces the consequences of a secret, Don regains his hunger to land bigger clients, and Sally experiences a milestone.","p":"/assets/stills/mad-men-s5e12.jpg"},{"t":"mad-men","s":5,"e":13,"n":"The Phantom","r":48,"y":"Don deals with a painful tooth, Roger pursues Megan's mother, Pete has a final meeting with Beth, and Megan seeks Don's help landing an audition.","p":"/assets/stills/mad-men-s5e13.jpg"},{"t":"mad-men","s":6,"e":1,"n":"The Doorway (1)","r":48,"y":"Over the holidays of 1967, Don and Megan vacation in Hawaii, a comedian complicates Peggy's ad campaign, and Roger receives difficult family news.","p":"/assets/stills/mad-men-s6e1.jpg"},{"t":"mad-men","s":6,"e":2,"n":"The Doorway (2)","r":48,"y":"Don befriends the doctor who lives in his building, Peggy works to salvage her campaign, Roger copes with a funeral, and Betty searches Greenwich Village for Sally's friend.","p":"/assets/stills/mad-men-s6e2.jpg"},{"t":"mad-men","s":6,"e":3,"n":"Collaborators","r":48,"y":"Don continues seeing a neighbor in secret, Pete's latest affair threatens his marriage, and Peggy picks up a valuable tip about a potential client.","p":"/assets/stills/mad-men-s6e3.jpg"},{"t":"mad-men","s":6,"e":4,"n":"To Have and to Hold","r":48,"y":"Don secretly works on a Heinz ketchup pitch, Megan prepares for a love scene on her soap opera, and Harry pushes for a promotion.","p":"/assets/stills/mad-men-s6e4.jpg"},{"t":"mad-men","s":6,"e":5,"n":"The Flood","r":48,"y":"As news of Martin Luther King Jr.'s assassination spreads, Peggy looks for a new apartment, Ginsberg is set up on a date, and Don spends the weekend with his kids.","p":"/assets/stills/mad-men-s6e5.jpg"},{"t":"mad-men","s":6,"e":6,"n":"For Immediate Release","r":48,"y":"With the firm planning to go public, Don and Pete's choices put major clients in jeopardy, while Roger leverages a connection to chase a huge prize.","p":"/assets/stills/mad-men-s6e6.jpg"},{"t":"mad-men","s":6,"e":7,"n":"Man With a Plan","r":48,"y":"Two agencies merge and work becomes awkward, Don asserts control in his affair, Pete faces his mother's decline, and Bob Benson helps an ill Joan.","p":"/assets/stills/mad-men-s6e7.jpg"},{"t":"mad-men","s":6,"e":8,"n":"The Crash","r":48,"y":"The creative department works through a frantic weekend fueled by a doctor's injections, while Don fixates on his affair and Sally confronts an intruder.","p":"/assets/stills/mad-men-s6e8.jpg"},{"t":"mad-men","s":6,"e":9,"n":"The Better Half","r":48,"y":"Peggy grows restless with her apartment and with Abe, Don spends an unexpected weekend with Betty, and Roger takes his grandson out.","p":"/assets/stills/mad-men-s6e9.jpg"},{"t":"mad-men","s":6,"e":10,"n":"A Tale of Two Cities","r":48,"y":"Don and Roger travel to Los Angeles to court a client, while back in New York Joan pursues an account on her own and Pete fumes.","p":"/assets/stills/mad-men-s6e10.jpg"},{"t":"mad-men","s":6,"e":11,"n":"Favors","r":48,"y":"Don tries to keep his neighbor's son out of the draft, Peggy battles a rat in her apartment, and Sally makes an accidental discovery.","p":"/assets/stills/mad-men-s6e11.jpg"},{"t":"mad-men","s":6,"e":12,"n":"The Quality of Mercy","r":48,"y":"Don clashes with Ted over a campaign and his relationship with Peggy, Sally interviews at a boarding school, and Pete digs into Bob Benson's background.","p":"/assets/stills/mad-men-s6e12.jpg"},{"t":"mad-men","s":6,"e":13,"n":"In Care Of","r":48,"y":"With pressure mounting in his personal and professional life, Don pushes for a change of scenery, while Pete's own life continues to unravel.","p":"/assets/stills/mad-men-s6e13.jpg"},{"t":"mad-men","s":7,"e":1,"n":"Time Zones","r":48,"y":"In early 1969, Don makes a new acquaintance on a flight, Joan has drinks with a client, Peggy hears a strong pitch, and Roger receives a puzzling call.","p":"/assets/stills/mad-men-s7e1.jpg"},{"t":"mad-men","s":7,"e":2,"n":"A Day's Work","r":48,"y":"Peggy misreads a flower delivery at the office, Pete navigates the politics of new business in California, and Joan lands in an awkward position.","p":"/assets/stills/mad-men-s7e2.jpg"},{"t":"mad-men","s":7,"e":3,"n":"Field Trip","r":48,"y":"Don takes an unplanned trip to Los Angeles, Betty has lunch with a friend, and the partners debate the terms of a key arrangement.","p":"/assets/stills/mad-men-s7e3.jpg"},{"t":"mad-men","s":7,"e":4,"n":"The Monolith","r":48,"y":"The agency prepares for the installation of a computer, Don reaches out to an old contact, Roger deals with family trouble, and Peggy feels underestimated.","p":"/assets/stills/mad-men-s7e4.jpg"},{"t":"mad-men","s":7,"e":5,"n":"The Runaways","r":48,"y":"Don receives an unexpected visitor connected to his past, Stan embarrasses a superior, and Harry discovers he has a new ally at the firm.","p":"/assets/stills/mad-men-s7e5.jpg"},{"t":"mad-men","s":7,"e":6,"n":"The Strategy","r":48,"y":"Peggy gathers research for a Burger Chef pitch, Pete is invited into an exclusive club, and Joan looks forward to time with a friend.","p":"/assets/stills/mad-men-s7e6.jpg"},{"t":"mad-men","s":7,"e":7,"n":"Waterloo","r":48,"y":"As the moon landing approaches, Don receives a troubling letter, Peggy prepares for a high-stakes pitch, and Roger gets an unexpected call.","p":"/assets/stills/mad-men-s7e7.jpg"},{"t":"mad-men","s":7,"e":8,"n":"Severance","r":48,"y":"In 1970, Don tries to track down a woman he thinks he knows, Joan tackles a problem with an account, and Peggy is set up on a date.","p":"/assets/stills/mad-men-s7e8.jpg"},{"t":"mad-men","s":7,"e":9,"n":"New Business","r":48,"y":"Roger offers Don advice he didn't ask for, Peggy and Stan disagree about personnel on an account, and Harry asks for Don's blessing.","p":"/assets/stills/mad-men-s7e9.jpg"},{"t":"mad-men","s":7,"e":10,"n":"The Forecast","r":48,"y":"Roger hands Don an assignment to write a vision for the agency's future, Joan travels to California on business, and Peggy and Pete disagree over a client.","p":"/assets/stills/mad-men-s7e10.jpg"},{"t":"mad-men","s":7,"e":11,"n":"Time & Life","r":48,"y":"Don comes up with a bold idea to protect the agency, Roger asks for Joan's help with a clerical error, and Peggy struggles to cast a commercial.","p":"/assets/stills/mad-men-s7e11.jpg"},{"t":"mad-men","s":7,"e":12,"n":"Lost Horizon","r":48,"y":"Don is rewarded for his work and is adjusting to a new environment, Joan clashes with a colleague over an account, and Roger dodges a big decision.","p":"/assets/stills/mad-men-s7e12.jpg"},{"t":"mad-men","s":7,"e":13,"n":"The Milk and Honey Route","r":54,"y":"On a solo road trip, Don stops in a small Oklahoma town, while Pete is approached by an old friend with a difficult offer.","p":"/assets/stills/mad-men-s7e13.jpg"},{"t":"mad-men","s":7,"e":14,"n":"Person to Person","r":58,"y":"The series finale follows Don Draper, his family, and his former colleagues as they confront where their lives are headed.","p":"/assets/stills/mad-men-s7e14.jpg"},{"t":"chernobyl","s":1,"e":1,"n":"1:23:45","r":61,"y":"In the early hours of April 1986, reactor operators and Pripyat firefighters scramble to make sense of a blast at the Soviet nuclear plant.","p":"/assets/stills/chernobyl-s1e1.jpg"},{"t":"chernobyl","s":1,"e":2,"n":"Please Remain Calm","r":66,"y":"As officials downplay the danger, scientist Valery Legasov is flown to the site while physicist Ulana Khomyuk races to warn Moscow of a looming second threat.","p":"/assets/stills/chernobyl-s1e2.jpg"},{"t":"chernobyl","s":1,"e":3,"n":"Open Wide, O Earth","r":64,"y":"Legasov sets out a cleanup plan with grim human costs, while a firefighter's wife defies warnings to stay near her husband in a Moscow hospital.","p":"/assets/stills/chernobyl-s1e3.jpg"},{"t":"chernobyl","s":1,"e":4,"n":"The Happiness of All Mankind","r":67,"y":"Legasov and Shcherbina look to machines and then soldiers to clear lethal rooftop debris, as Khomyuk runs into state obstruction while investigating the accident's cause.","p":"/assets/stills/chernobyl-s1e4.jpg"},{"t":"chernobyl","s":1,"e":5,"n":"Vichnaya Pamyat","r":73,"y":"At a trial in a contaminated town, Legasov, Shcherbina and Khomyuk weigh what speaking honestly about the disaster could cost them personally.","p":"/assets/stills/chernobyl-s1e5.jpg"},{"t":"the-sopranos","s":1,"e":1,"n":"The Sopranos","r":60,"y":"New Jersey mob boss Tony Soprano reluctantly begins therapy with Dr. Jennifer Melfi after a series of panic attacks, opening up about family and business.","p":"/assets/stills/the-sopranos-s1e1.jpg"},{"t":"the-sopranos","s":1,"e":2,"n":"46 Long","r":50,"y":"With the acting boss gravely ill, Tony maneuvers around his uncle Junior, while Christopher hijacks a truck of DVD players and Tony pushes his mother into a retirement home.","p":"/assets/stills/the-sopranos-s1e2.jpg"},{"t":"the-sopranos","s":1,"e":3,"n":"Denial, Anger, Acceptance","r":45,"y":"Junior's associate stokes his suspicion of Tony, while Tony, Paulie and Silvio take on a family problem for a Hasidic motel owner.","p":"/assets/stills/the-sopranos-s1e3.jpg"},{"t":"the-sopranos","s":1,"e":4,"n":"Meadowlands","r":53,"y":"Tony faces a hard leadership choice as Jackie Aprile's health declines, A.J. learns more about his father's work, and Tony has Dr. Melfi investigated.","p":"/assets/stills/the-sopranos-s1e4.jpg"},{"t":"the-sopranos","s":1,"e":5,"n":"College","r":57,"y":"While touring Maine colleges with Meadow, Tony spots someone he believes is a former mobster turned informant; back home, Carmela spends an evening with Father Phil.","p":"/assets/stills/the-sopranos-s1e5.jpg"},{"t":"the-sopranos","s":1,"e":6,"n":"Pax Soprana","r":50,"y":"Tony arranges for Junior to become the new boss, surprises Dr. Melfi during a session, and struggles with side effects that frustrate the women in his life.","p":"/assets/stills/the-sopranos-s1e6.jpg"},{"t":"the-sopranos","s":1,"e":7,"n":"Down Neck","r":52,"y":"After A.J. gets into trouble at school, Tony worries his own influence is to blame and recalls childhood memories of his father's line of work.","p":"/assets/stills/the-sopranos-s1e7.jpg"},{"t":"the-sopranos","s":1,"e":8,"n":"The Legend of Tennessee Moltisanti","r":49,"y":"News of coming federal indictments sends the crew scrambling to clean house, while a restless Christopher feels overlooked and grows agitated.","p":"/assets/stills/the-sopranos-s1e8.jpg"},{"t":"the-sopranos","s":1,"e":9,"n":"Boca","r":52,"y":"Junior's private life becomes awkward gossip, and controversy erupts when the coach of Meadow's soccer team announces he is leaving the school.","p":"/assets/stills/the-sopranos-s1e9.jpg"},{"t":"the-sopranos","s":1,"e":10,"n":"A Hit Is a Hit","r":53,"y":"Christopher and Adriana try breaking into the music industry, while a rapper presses Hesh about old royalties and Tony golfs with his neighbor's friends.","p":"/assets/stills/the-sopranos-s1e10.jpg"},{"t":"the-sopranos","s":1,"e":11,"n":"Nobody Knows Anything","r":50,"y":"After an FBI raid, Tony is told that Pussy might be cooperating with authorities, and he sends Paulie to find out whether the rumor is true.","p":"/assets/stills/the-sopranos-s1e11.jpg"},{"t":"the-sopranos","s":1,"e":12,"n":"Isabella","r":47,"y":"Deep in depression and a medicated haze, Tony is intrigued by a young Italian dental student staying next door, while danger closes in around him.","p":"/assets/stills/the-sopranos-s1e12.jpg"},{"t":"the-sopranos","s":1,"e":13,"n":"I Dream of Jeannie Cusamano","r":61,"y":"In the season finale, Tony learns troubling information about a possible betrayal and confronts the fallout of his therapy becoming common knowledge.","p":"/assets/stills/the-sopranos-s1e13.jpg"},{"t":"the-sopranos","s":2,"e":1,"n":"Guy Walks into a Psychiatrist's Office","r":49,"y":"Season two opens with Tony settling in as boss, Junior in jail, Dr. Melfi refusing to see him, and his sister Janice arriving in town.","p":"/assets/stills/the-sopranos-s2e1.jpg"},{"t":"the-sopranos","s":2,"e":2,"n":"Do Not Resuscitate","r":50,"y":"When protesters picket a construction site, Tony works both sides to resolve it, while Janice gets drawn into managing Livia's affairs.","p":"/assets/stills/the-sopranos-s2e2.jpg"},{"t":"the-sopranos","s":2,"e":3,"n":"Toodle-Fucking-Oo","r":51,"y":"Tony catches Meadow throwing a party at her grandmother's empty house, and newly released Richie Aprile wastes no time looking for action.","p":"/assets/stills/the-sopranos-s2e3.jpg"},{"t":"the-sopranos","s":2,"e":4,"n":"Commendatori","r":52,"y":"Tony travels to Naples with Paulie and Christopher to set up a car-theft operation, where Tony negotiates with a powerful family and Paulie seeks his roots.","p":"/assets/stills/the-sopranos-s2e4.jpg"},{"t":"the-sopranos","s":2,"e":5,"n":"Big Girls Don't Cry","r":52,"y":"New recruit Furio makes a forceful first impression in New Jersey, Dr. Melfi discusses her guilt with her therapist, and Christopher tries acting classes.","p":"/assets/stills/the-sopranos-s2e5.jpg"},{"t":"the-sopranos","s":2,"e":6,"n":"The Happy Wanderer","r":51,"y":"A gambling father of Meadow's friend falls deep into debt at Tony's poker game, while a funeral forces Tony to deal with Livia.","p":"/assets/stills/the-sopranos-s2e6.jpg"},{"t":"the-sopranos","s":2,"e":7,"n":"D-Girl","r":56,"y":"As A.J.'s confirmation approaches, his parents worry about his apathy, while Christopher's interest in Hollywood is rekindled by a film-industry connection.","p":"/assets/stills/the-sopranos-s2e7.jpg"},{"t":"the-sopranos","s":2,"e":8,"n":"Full Leather Jacket","r":43,"y":"Richie tries to make peace with Tony after a dispute, while two of Christopher's frustrated associates make a bold move to prove themselves.","p":"/assets/stills/the-sopranos-s2e8.jpg"},{"t":"the-sopranos","s":2,"e":9,"n":"From Where to Eternity","r":55,"y":"Christopher has a frightening near-death experience that unsettles Paulie, Carmela pushes Tony on a vasectomy, and Dr. Melfi confides in her own therapist.","p":"/assets/stills/the-sopranos-s2e9.jpg"},{"t":"the-sopranos","s":2,"e":10,"n":"Bust Out","r":59,"y":"Richie complains to Tony and then to Junior, Tony slowly drains a gambling-addicted store owner's business, and Carmela meets a charming neighbor.","p":"/assets/stills/the-sopranos-s2e10.jpg"},{"t":"the-sopranos","s":2,"e":11,"n":"House Arrest","r":57,"y":"Advised by his lawyer to appear legitimate, Tony spends days at a waste management office, while Junior finds company during his house arrest.","p":"/assets/stills/the-sopranos-s2e11.jpg"},{"t":"the-sopranos","s":2,"e":12,"n":"The Knight in White Satin Armor","r":60,"y":"Engaged couple Richie and Janice have an explosive argument, while Irina takes desperate steps to win Tony back.","p":"/assets/stills/the-sopranos-s2e12.jpg"},{"t":"the-sopranos","s":2,"e":13,"n":"Funhouse","r":59,"y":"In the season finale, Tony suffers food poisoning that sends him into vivid fever dreams, helping him confront a suspicion he has avoided.","p":"/assets/stills/the-sopranos-s2e13.jpg"},{"t":"the-sopranos","s":3,"e":1,"n":"Mr. Ruggerio's Neighborhood","r":49,"y":"The FBI launches an elaborate operation to plant a listening device in the Soprano home, while Tony handles questions from a grieving soldier.","p":"/assets/stills/the-sopranos-s3e1.jpg"},{"t":"the-sopranos","s":3,"e":2,"n":"Proshai, Livushka","r":57,"y":"A death in the family brings Janice back to arrange a funeral, as Tony struggles with conflicting feelings and the gathering takes strange turns.","p":"/assets/stills/the-sopranos-s3e2.jpg"},{"t":"the-sopranos","s":3,"e":3,"n":"Fortunate Son","r":59,"y":"Christopher learns that being a made man brings new pressures, while Janice moves into her mother's house and settles a dispute with the former caretaker.","p":"/assets/stills/the-sopranos-s3e3.jpg"},{"t":"the-sopranos","s":3,"e":4,"n":"Employee of the Month","r":53,"y":"Dr. Melfi's plan to steer Tony toward behavioral therapy is interrupted by a personal crisis, and Ralph Cifaretto takes Jackie Jr. under his wing.","p":"/assets/stills/the-sopranos-s3e4.jpg"},{"t":"the-sopranos","s":3,"e":5,"n":"Another Toothpick","r":60,"y":"A retired hit man comes out of retirement to handle a young hothead, worrying his son Bobby and Uncle Junior.","p":"/assets/stills/the-sopranos-s3e5.jpg"},{"t":"the-sopranos","s":3,"e":6,"n":"University","r":49,"y":"Ralph's troubled relationship with a Bada Bing dancer disrupts nights at the club, while Meadow's college romance is tested by a needy roommate.","p":"/assets/stills/the-sopranos-s3e6.jpg"},{"t":"the-sopranos","s":3,"e":7,"n":"Second Opinion","r":60,"y":"Tony pushes Junior to get a second opinion on his cancer care, while Carmela debates seeing a therapist of her own.","p":"/assets/stills/the-sopranos-s3e7.jpg"},{"t":"the-sopranos","s":3,"e":8,"n":"He Is Risen","r":54,"y":"As Thanksgiving approaches, Tony's feud with Ralph escalates despite Johnny Sack's mediation, while Meadow and Jackie Jr. grow closer.","p":"/assets/stills/the-sopranos-s3e8.jpg"},{"t":"the-sopranos","s":3,"e":9,"n":"The Telltale Moozadell","r":56,"y":"Tony gives Carmela a birthday present, Christopher hands Adriana a nightclub of her own, and A.J. gets in trouble for vandalizing the school pool.","p":"/assets/stills/the-sopranos-s3e9.jpg"},{"t":"the-sopranos","s":3,"e":10,"n":"To Save Us All from Satan's Power","r":46,"y":"A Christmas season visit with old memories sends Tony back to Melfi, while Bobby reluctantly agrees to take over as Santa at the holiday party.","p":"/assets/stills/the-sopranos-s3e10.jpg"},{"t":"the-sopranos","s":3,"e":11,"n":"Pine Barrens","r":60,"y":"Paulie and Christopher get stranded in the snowy South Jersey woods after a debt collection goes wrong, while Tony juggles his family and his girlfriend.","p":"/assets/stills/the-sopranos-s3e11.jpg"},{"t":"the-sopranos","s":3,"e":12,"n":"Amour Fou","r":60,"y":"Inspired by Ralph's stories, Jackie Jr. plans to rob a card game to make a name for himself, while Tony's affair with Gloria grows turbulent.","p":"/assets/stills/the-sopranos-s3e12.jpg"},{"t":"the-sopranos","s":3,"e":13,"n":"Army of One","r":60,"y":"In the season finale, A.J.'s latest school trouble has his parents considering military school, while Tony makes demands of Ralph regarding Jackie Jr.","p":"/assets/stills/the-sopranos-s3e13.jpg"},{"t":"the-sopranos","s":4,"e":1,"n":"For All Debts Public and Private","r":58,"y":"Tony invests in a land deal despite Carmela's money worries, Junior's trial approaches, and Adriana brings a new friend to Sunday dinner.","p":"/assets/stills/the-sopranos-s4e1.jpg"},{"t":"the-sopranos","s":4,"e":2,"n":"No-Show","r":58,"y":"With Paulie in prison, Christopher becomes acting captain and gets off to a rocky start, while Meadow considers taking a year off from college.","p":"/assets/stills/the-sopranos-s4e2.jpg"},{"t":"the-sopranos","s":4,"e":3,"n":"Christopher","r":54,"y":"Silvio and Ralph handle a planned Native American protest of the Columbus Day parade, while Carmela is embarrassed at an Italian pride luncheon.","p":"/assets/stills/the-sopranos-s4e3.jpg"},{"t":"the-sopranos","s":4,"e":4,"n":"The Weight","r":58,"y":"A crude joke about his wife sends Johnny Sack on a vendetta that tests Tony's diplomacy, and Furio hosts a housewarming party.","p":"/assets/stills/the-sopranos-s4e4.jpg"},{"t":"the-sopranos","s":4,"e":5,"n":"Pie-O-My","r":55,"y":"While visiting Ralph's racehorse, Tony develops an unexpected bond with the animal, and Adriana's nightclub becomes a gathering spot for Christopher's crew.","p":"/assets/stills/the-sopranos-s4e5.jpg"},{"t":"the-sopranos","s":4,"e":6,"n":"Everybody Hurts","r":55,"y":"Artie lends money to the brother of his new hostess, Christopher takes on new duties, and Carmela sets Furio up on a date.","p":"/assets/stills/the-sopranos-s4e6.jpg"},{"t":"the-sopranos","s":4,"e":7,"n":"Watching Too Much Television","r":54,"y":"Paulie returns from prison to a celebration and old tensions quickly resurface, while Tony and Ralph pursue a real estate scheme suggested by Carmela's cousin.","p":"/assets/stills/the-sopranos-s4e7.jpg"},{"t":"the-sopranos","s":4,"e":8,"n":"Mergers and Acquisitions","r":56,"y":"Paulie tries to help his mother fit in at her retirement community, Furio visits his ailing father in Italy, and Ralph introduces Tony to his new girlfriend.","p":"/assets/stills/the-sopranos-s4e8.jpg"},{"t":"the-sopranos","s":4,"e":9,"n":"Whoever Did This","r":58,"y":"Junior's legal team tries a new strategy after damaging press coverage, Ralph plays pranks at Paulie's expense, and Tony finds solace at the stables.","p":"/assets/stills/the-sopranos-s4e9.jpg"},{"t":"the-sopranos","s":4,"e":10,"n":"The Strong, Silent Type","r":53,"y":"Tony describes himself to Melfi as a sad clown, Carmela drags A.J. along to help Furio decorate, and the crew stages an intervention for a struggling member.","p":"/assets/stills/the-sopranos-s4e10.jpg"},{"t":"the-sopranos","s":4,"e":11,"n":"Calling All Cars","r":48,"y":"After a sitdown with the New York family, Tony reconsiders a business partnership, while Janice grows impatient with Bobby and Melfi probes Tony's dreams.","p":"/assets/stills/the-sopranos-s4e11.jpg"},{"t":"the-sopranos","s":4,"e":12,"n":"Eloise","r":56,"y":"Tony continues negotiating with New York over Esplanade profits, Carmela makes plans she can't keep, and Furio accompanies Tony to a casino.","p":"/assets/stills/the-sopranos-s4e12.jpg"},{"t":"the-sopranos","s":4,"e":13,"n":"Whitecaps","r":75,"y":"In the season finale, Tony and Carmela consider buying a beach house, but a voice from Tony's past threatens to unravel their plans.","p":"/assets/stills/the-sopranos-s4e13.jpg"},{"t":"the-sopranos","s":5,"e":1,"n":"Two Tonys","r":54,"y":"A wave of paroled gangsters changes the balance between the New Jersey and New York families, while Tony adjusts to life apart from Carmela.","p":"/assets/stills/the-sopranos-s5e1.jpg"},{"t":"the-sopranos","s":5,"e":2,"n":"Rat Pack","r":57,"y":"Tony welcomes his cousin Tony Blundetto home after years in prison, while Carmela launches a film club and Adriana wrestles with guilt.","p":"/assets/stills/the-sopranos-s5e2.jpg"},{"t":"the-sopranos","s":5,"e":3,"n":"Where's Johnny?","r":55,"y":"Johnny Sack bristles at Tony's power-sharing approach, a paroled old-timer crosses Paulie in the landscaping business, and Tony finds a new place to stay.","p":"/assets/stills/the-sopranos-s5e3.jpg"},{"t":"the-sopranos","s":5,"e":4,"n":"All Happy Families","r":53,"y":"Tony and Carmela meet to discuss A.J.'s dim college prospects, an old-school associate entertains the crew with stories, and A.J. enjoys a night in Manhattan.","p":"/assets/stills/the-sopranos-s5e4.jpg"},{"t":"the-sopranos","s":5,"e":5,"n":"Irregular Around the Margins","r":52,"y":"While Christopher is away, Tony gives Adriana a ride that ends badly, and the story gets distorted as it spreads through the crew.","p":"/assets/stills/the-sopranos-s5e5.jpg"},{"t":"the-sopranos","s":5,"e":6,"n":"Sentimental Education","r":55,"y":"Carmela spends extra time with A.J.'s guidance counselor as she pushes for his future, while Tony Blundetto finds that going straight is harder than expected.","p":"/assets/stills/the-sopranos-s5e6.jpg"},{"t":"the-sopranos","s":5,"e":7,"n":"In Camelot","r":55,"y":"A conversation with his late father's former mistress reveals unsettling things to Tony, while Christopher struggles with a friend's addiction.","p":"/assets/stills/the-sopranos-s5e7.jpg"},{"t":"the-sopranos","s":5,"e":8,"n":"Marco Polo","r":54,"y":"Family and friends gather at the Soprano house for Carmela's father's 75th birthday, while Tony B. weighs an offer that could change his future.","p":"/assets/stills/the-sopranos-s5e8.jpg"},{"t":"the-sopranos","s":5,"e":9,"n":"Unidentified Black Males","r":59,"y":"Tony's relationship with Johnny Sack becomes strained over rumors, Meadow helps her boyfriend find work, and A.J. faces a strict summer at home.","p":"/assets/stills/the-sopranos-s5e9.jpg"},{"t":"the-sopranos","s":5,"e":10,"n":"Cold Cuts","r":53,"y":"Tony B. and Christopher reminisce on a country trip, Janice ends up in anger management, and Tony plans another party with Carmela.","p":"/assets/stills/the-sopranos-s5e10.jpg"},{"t":"the-sopranos","s":5,"e":11,"n":"The Test Dream","r":50,"y":"Tony checks into the Plaza Hotel for a restful night, but his sleep fills with strange dreams populated by figures from his past.","p":"/assets/stills/the-sopranos-s5e11.jpg"},{"t":"the-sopranos","s":5,"e":12,"n":"Long Term Parking","r":57,"y":"With federal agents pressing her, Adriana weighs her options, while Tony and his cousin have a frank conversation and Carmela gets a real-estate offer.","p":"/assets/stills/the-sopranos-s5e12.jpg"},{"t":"the-sopranos","s":5,"e":13,"n":"All Due Respect","r":55,"y":"In the season finale, Tony's crew braces for pressure from Johnny Sack, Christopher has a startling visitor, and Carmela reflects on her blessings.","p":"/assets/stills/the-sopranos-s5e13.jpg"},{"t":"the-sopranos","s":6,"e":1,"n":"Members Only","r":52,"y":"A former associate tries to leave mob life behind, while Junior's growing confusion and paranoia make him a danger to those around him.","p":"/assets/stills/the-sopranos-s6e1.jpg"},{"t":"the-sopranos","s":6,"e":2,"n":"Join the Club","r":54,"y":"The family copes with a sudden crisis, while Tony experiences a strange parallel existence as a traveling salesman in California.","p":"/assets/stills/the-sopranos-s6e2.jpg"},{"t":"the-sopranos","s":6,"e":3,"n":"Mayham","r":56,"y":"While the crew squabbles over power and money, Tony finds himself suspended in a dreamlike place on the threshold.","p":"/assets/stills/the-sopranos-s6e3.jpg"},{"t":"the-sopranos","s":6,"e":4,"n":"The Fleshy Part of the Thigh","r":58,"y":"Tony returns home and to business with a renewed perspective, while Paulie receives startling news about his mother.","p":"/assets/stills/the-sopranos-s6e4.jpg"},{"t":"the-sopranos","s":6,"e":5,"n":"Mr. & Mrs. John Sacrimoni Request...","r":53,"y":"Johnny Sack seeks permission to leave prison for his daughter's wedding, while Tony looks for ways to assert his strength.","p":"/assets/stills/the-sopranos-s6e5.jpg"},{"t":"the-sopranos","s":6,"e":6,"n":"Live Free or Die","r":55,"y":"Tony seeks advice to handle a sensitive problem with a top earner, and must decide whether the man deserves another chance.","p":"/assets/stills/the-sopranos-s6e6.jpg"},{"t":"the-sopranos","s":6,"e":7,"n":"Luxury Lounge","r":55,"y":"Christopher travels to Los Angeles to court a Hollywood star for his film project, while Artie's hospitality is abused at his restaurant.","p":"/assets/stills/the-sopranos-s6e7.jpg"},{"t":"the-sopranos","s":6,"e":8,"n":"Johnny Cakes","r":54,"y":"Vito, hiding out in New Hampshire, considers starting a new life, while A.J. struggles with feelings of revenge.","p":"/assets/stills/the-sopranos-s6e8.jpg"},{"t":"the-sopranos","s":6,"e":9,"n":"The Ride","r":54,"y":"Paulie faces public anger after an accident at a church festival, while Christopher tries to settle into life as a husband and father.","p":"/assets/stills/the-sopranos-s6e9.jpg"},{"t":"the-sopranos","s":6,"e":10,"n":"Moe n' Joe","r":54,"y":"Tony reflects on how growing up with Janice shaped him, while Vito tries to build a new life in New Hampshire.","p":"/assets/stills/the-sopranos-s6e10.jpg"},{"t":"the-sopranos","s":6,"e":11,"n":"Cold Stones","r":56,"y":"Phil Leotardo looks to settle a score, while Tony grows frustrated with A.J.'s lack of ambition and work ethic.","p":"/assets/stills/the-sopranos-s6e11.jpg"},{"t":"the-sopranos","s":6,"e":12,"n":"Kaisha","r":59,"y":"Tensions between New York and New Jersey keep simmering, Christopher wrestles with addiction, Carmela works on her spec house, and A.J. has a new girlfriend.","p":"/assets/stills/the-sopranos-s6e12.jpg"},{"t":"the-sopranos","s":6,"e":13,"n":"Soprano Home Movies","r":52,"y":"Bobby and Janice host Tony's birthday weekend at their Adirondacks lake house, where old resentments surface over drinks and board games.","p":"/assets/stills/the-sopranos-s6e13.jpg"},{"t":"the-sopranos","s":6,"e":14,"n":"Stage 5","r":56,"y":"Christopher's horror film premieres, revealing how he feels about Tony, while Johnny Sack faces a health crisis and power shifts in New York.","p":"/assets/stills/the-sopranos-s6e14.jpg"},{"t":"the-sopranos","s":6,"e":15,"n":"Remember When","r":58,"y":"When an old crime threatens to resurface, Tony and Paulie head to Florida, where Tony weighs their long friendship.","p":"/assets/stills/the-sopranos-s6e15.jpg"},{"t":"the-sopranos","s":6,"e":16,"n":"Chasing It","r":50,"y":"Tony's luck sours as a gambling streak strains his friendship with Hesh, while A.J. makes a significant decision about his future.","p":"/assets/stills/the-sopranos-s6e16.jpg"},{"t":"the-sopranos","s":6,"e":17,"n":"Walk Like a Man","r":56,"y":"The relationship between Christopher and Paulie falters, while A.J. sinks into depression after a breakup.","p":"/assets/stills/the-sopranos-s6e17.jpg"},{"t":"the-sopranos","s":6,"e":18,"n":"Kennedy and Heidi","r":53,"y":"The New Jersey and New York families clash over an asbestos job, while Tony deals with a problematic associate and A.J. questions his friendships.","p":"/assets/stills/the-sopranos-s6e18.jpg"},{"t":"the-sopranos","s":6,"e":19,"n":"The Second Coming","r":53,"y":"Tony tries to mend the rift between New Jersey and New York, A.J.'s struggle with depression continues, and a New York associate crosses a line with Meadow.","p":"/assets/stills/the-sopranos-s6e19.jpg"},{"t":"the-sopranos","s":6,"e":20,"n":"The Blue Comet","r":51,"y":"Suspicion of disloyalty hangs over Tony's crew as Phil Leotardo weighs how to handle his escalating conflict with the Sopranos.","p":"/assets/stills/the-sopranos-s6e20.jpg"},{"t":"the-sopranos","s":6,"e":21,"n":"Made in America","r":61,"y":"In the series finale, Tony seeks a resolution with New York while worrying about a possible informant, and the family gathers amid uncertainty.","p":"/assets/stills/the-sopranos-s6e21.jpg"},{"t":"mare-of-easttown","s":1,"e":1,"n":"Miss Lady Hawk Herself","r":58,"y":"In a small Pennsylvania town, detective Mare Sheehan responds to a prowler call while facing local pressure to solve a year-old missing-person case.","p":"/assets/stills/mare-of-easttown-s1e1.jpg"},{"t":"mare-of-easttown","s":1,"e":2,"n":"Fathers","r":58,"y":"Mare investigates a grim crime scene and breaks hard news to a grieving father, while a county detective is assigned to help her.","p":"/assets/stills/mare-of-easttown-s1e2.jpg"},{"t":"mare-of-easttown","s":1,"e":3,"n":"Enter Number Two","r":59,"y":"As Mare and partner Colin Zabel examine new evidence, phone records point to an unexpected suspect, and Mare's family tensions over her grandson escalate.","p":"/assets/stills/mare-of-easttown-s1e3.jpg"},{"t":"mare-of-easttown","s":1,"e":4,"n":"Poor Sisyphus","r":56,"y":"Sidelined from the case, Mare watches as Colin questions a local priest about his past, while an anonymous call gives a worried mother new hope.","p":"/assets/stills/mare-of-easttown-s1e4.jpg"},{"t":"mare-of-easttown","s":1,"e":5,"n":"Illusions","r":59,"y":"In mandated therapy, Mare opens up about her family's history, while her best friend Lori tries to understand her son's troubling behavior at school.","p":"/assets/stills/mare-of-easttown-s1e5.jpg"},{"t":"mare-of-easttown","s":1,"e":6,"n":"Sore Must Be the Storm","r":59,"y":"Recovering in the hospital after a dangerous encounter, Mare gets another shot at the case from her chief and starts revisiting old suspects.","p":"/assets/stills/mare-of-easttown-s1e6.jpg"},{"t":"mare-of-easttown","s":1,"e":7,"n":"Sacrament","r":66,"y":"As her investigation reaches a turning point, Mare and her community grapple with the case and its effects on the people closest to her.","p":"/assets/stills/mare-of-easttown-s1e7.jpg"},{"t":"the-queens-gambit","s":1,"e":1,"n":"Openings","r":59,"y":"After losing her mother, young Beth Harmon is placed in a Kentucky orphanage, where the custodian introduces her to chess.","p":"/assets/stills/the-queens-gambit-s1e1.jpg"},{"t":"the-queens-gambit","s":1,"e":2,"n":"Exchanges","r":65,"y":"Adopted by a suburban couple, teenage Beth navigates an awkward high school life and schemes to enter her first chess tournament.","p":"/assets/stills/the-queens-gambit-s1e2.jpg"},{"t":"the-queens-gambit","s":1,"e":3,"n":"Doubled Pawns","r":46,"y":"Beth and her adoptive mother begin traveling the tournament circuit, attracting press attention as Beth aims for the U.S. Open in Las Vegas.","p":"/assets/stills/the-queens-gambit-s1e3.jpg"},{"t":"the-queens-gambit","s":1,"e":4,"n":"Middle Game","r":49,"y":"A Russian class leads Beth into a new social circle, and a tournament in Mexico City brings her face to face with world champion Borgov.","p":"/assets/stills/the-queens-gambit-s1e4.jpg"},{"t":"the-queens-gambit","s":1,"e":5,"n":"Fork","r":48,"y":"Back home in Kentucky, Beth accepts training help from a former opponent as she prepares for the U.S. Championship.","p":"/assets/stills/the-queens-gambit-s1e5.jpg"},{"t":"the-queens-gambit","s":1,"e":6,"n":"Adjournment","r":60,"y":"After intense preparation in New York, Beth travels to Paris for a rematch with Borgov, but a night out threatens her focus.","p":"/assets/stills/the-queens-gambit-s1e6.jpg"},{"t":"the-queens-gambit","s":1,"e":7,"n":"End Game","r":68,"y":"A visit from an old friend pushes Beth to confront her past as she heads to Moscow for the most important tournament of her career.","p":"/assets/stills/the-queens-gambit-s1e7.jpg"},{"t":"the-wire","s":1,"e":1,"n":"The Target","r":63,"y":"After embarrassing his bosses in court, detective Jimmy McNulty is shunted onto a mismatched unit tasked with building a case against West Baltimore drug boss Avon Barksdale.","p":"/assets/stills/the-wire-s1e1.jpg"},{"t":"the-wire","s":1,"e":2,"n":"The Detail","r":58,"y":"A key courtroom witness turns up dead, raising the stakes for McNulty, while Kima Greggs learns the Barksdale hierarchy and a reckless night raid at the towers goes badly.","p":"/assets/stills/the-wire-s1e2.jpg"},{"t":"the-wire","s":1,"e":3,"n":"The Buys","r":56,"y":"Herc, Carver and Prez stir up a neighborhood uproar with a heavy-handed early sweep, while D'Angelo uses a chessboard to explain the drug trade to his young crew.","p":"/assets/stills/the-wire-s1e3.jpg"},{"t":"the-wire","s":1,"e":4,"n":"Old Cases","r":60,"y":"The detail leans on an arrested dealer to cooperate, Avon puts a price on stick-up man Omar, and McNulty brings informant Bubbles along on an unusual outing.","p":"/assets/stills/the-wire-s1e4.jpg"},{"t":"the-wire","s":1,"e":5,"n":"The Pager","r":60,"y":"Cloned pagers finally give the detail a window into the Barksdale crew, but the numbers come in a code that nobody on the team can read at first.","p":"/assets/stills/the-wire-s1e5.jpg"},{"t":"the-wire","s":1,"e":6,"n":"The Wire","r":60,"y":"Pressured to close three murders quickly, the brass want arrests now, so McNulty and Greggs fight to protect the slow, patient wiretap investigation they have built.","p":"/assets/stills/the-wire-s1e6.jpg"},{"t":"the-wire","s":1,"e":7,"n":"One Arrest","r":60,"y":"A seizure based on intercepted calls puts Avon and Stringer on guard, while Bunk and McNulty go hunting for another witness to the Gant murder.","p":"/assets/stills/the-wire-s1e7.jpg"},{"t":"the-wire","s":1,"e":8,"n":"Lessons","r":57,"y":"McNulty gets a lead on Stringer Bell's car from an unexpected place, Greggs and Carver stop a political aide carrying cash, and Omar's war with Barksdale escalates.","p":"/assets/stills/the-wire-s1e8.jpg"},{"t":"the-wire","s":1,"e":9,"n":"Game Day","r":57,"y":"Avon flexes his wealth in a heated rivalry with an east side crew, while Herc and Carver grab a bag of money and Omar makes his presence felt again.","p":"/assets/stills/the-wire-s1e9.jpg"},{"t":"the-wire","s":1,"e":10,"n":"The Cost","r":56,"y":"The detail must figure out how to protect young witness Wallace until trial, Prez reveals a knack for tracing money, and McNulty's family life grows more strained.","p":"/assets/stills/the-wire-s1e10.jpg"},{"t":"the-wire","s":1,"e":11,"n":"The Hunt","r":57,"y":"Commanders demand flashy arrests for the cameras, Barksdale's ranks thin after recent violence, Bubbles tries to stay clean, and Freamon suspects someone is leaking information.","p":"/assets/stills/the-wire-s1e11.jpg"},{"t":"the-wire","s":1,"e":12,"n":"Cleaning Up","r":57,"y":"With the pay phones gone dark, the detail tries to get inside Avon's office, D'Angelo travels to New York on an errand, and Daniels battles the department's politics.","p":"/assets/stills/the-wire-s1e12.jpg"},{"t":"the-wire","s":1,"e":13,"n":"Sentencing","r":66,"y":"As pressure mounts on the Barksdale organization, Daniels and McNulty look beyond their chain of command to push the case forward in the season one finale.","p":"/assets/stills/the-wire-s1e13.jpg"},{"t":"the-wire","s":2,"e":1,"n":"Ebb Tide","r":59,"y":"Exiled to the marine unit, McNulty finds something disturbing in the harbor, while the Barksdale crew seeks new suppliers and Stringer Bell meets with wary partners in New York.","p":"/assets/stills/the-wire-s2e1.jpg"},{"t":"the-wire","s":2,"e":2,"n":"Collateral Damage","r":59,"y":"A petty feud between police major Valchek and dockworkers' union leader Frank Sobotka escalates, while Avon keeps running his business from behind prison walls.","p":"/assets/stills/the-wire-s2e2.jpg"},{"t":"the-wire","s":2,"e":3,"n":"Hot Shots","r":59,"y":"Bunk and Freamon follow a case up the coast to Philadelphia, Daniels chafes at his dead-end posting, and Stringer arranges a setup on Avon's behalf inside the prison.","p":"/assets/stills/the-wire-s2e3.jpg"},{"t":"the-wire","s":2,"e":4,"n":"Hard Cases","r":59,"y":"Frank Sobotka scolds his nephew Nick over a botched side deal, while McNulty obsesses over an unidentified body and Bunk is sent looking for Omar to testify.","p":"/assets/stills/the-wire-s2e4.jpg"},{"t":"the-wire","s":2,"e":5,"n":"Undertow","r":58,"y":"Ziggy loses his beloved car to local dealers, homicide hands out grand jury summonses on the docks, and port officer Beadie Russell digs into how cargo vanishes.","p":"/assets/stills/the-wire-s2e5.jpg"},{"t":"the-wire","s":2,"e":6,"n":"All Prologue","r":59,"y":"McNulty tries to let go of police work and focus on his marriage, while the detectives trace a computer pattern linked to the port and Sobotka lobbies politicians.","p":"/assets/stills/the-wire-s2e6.jpg"},{"t":"the-wire","s":2,"e":7,"n":"Backwash","r":59,"y":"The detail secretly tracks shipping containers through a cloned port computer, and Greggs and Prez stumble onto a ring of trafficked women operating in the city.","p":"/assets/stills/the-wire-s2e7.jpg"},{"t":"the-wire","s":2,"e":8,"n":"Duck and Cover","r":58,"y":"McNulty drifts back into drinking, Ziggy endures another humiliation on the docks, and the long-sought wiretap finally comes online as Sobotka meets his shadowy business partners.","p":"/assets/stills/the-wire-s2e8.jpg"},{"t":"the-wire","s":2,"e":9,"n":"Stray Rounds","r":59,"y":"Bodie's sales push sparks fresh trouble on the corners, Ziggy hatches a risky scheme, and McNulty waits nervously during an undercover assignment inside a brothel.","p":"/assets/stills/the-wire-s2e9.jpg"},{"t":"the-wire","s":2,"e":10,"n":"Storm Warnings","r":59,"y":"Satellite tracking gives the detail an edge, Bodie bristles at rivals working his turf, Stringer considers an unusual fix, and Ziggy's partnership with a fence turns tense.","p":"/assets/stills/the-wire-s2e10.jpg"},{"t":"the-wire","s":2,"e":11,"n":"Bad Dreams","r":59,"y":"Racing against time, the detail makes a bold play as Sobotka faces mounting bad news, Nick tries to mend fences with the Greeks, and Omar acts on his suspicions.","p":"/assets/stills/the-wire-s2e11.jpg"},{"t":"the-wire","s":2,"e":12,"n":"Port in a Storm","r":63,"y":"In the second season finale, the detail regroups after a setback while Bunk and Russell return to Philadelphia and Stringer faces pressure from both Avon and Brother Mouzone.","p":"/assets/stills/the-wire-s2e12.jpg"},{"t":"the-wire","s":3,"e":1,"n":"Time After Time","r":59,"y":"The demolition of the Franklin Terrace towers scatters the Barksdale crew, Stringer tries a new business approach, and McNulty's unit goes after Proposition Joe's operation.","p":"/assets/stills/the-wire-s3e1.jpg"},{"t":"the-wire","s":3,"e":2,"n":"All Due Respect","r":59,"y":"Omar keeps raiding Barksdale stash houses, Bodie is ordered to confront ambitious young dealer Marlo Stanfield, and McNulty quietly reopens a closed case from the previous year.","p":"/assets/stills/the-wire-s3e2.jpg"},{"t":"the-wire","s":3,"e":3,"n":"Dead Soldiers","r":59,"y":"Major Colvin gets grilled over crime statistics at a tense Comstat meeting, a compromised wiretap forces a change of target, and Carcetti cultivates influence at City Hall.","p":"/assets/stills/the-wire-s3e3.jpg"},{"t":"the-wire","s":3,"e":4,"n":"Amsterdam","r":59,"y":"Colvin surprises a community meeting with blunt honesty, Bubbles finds an unlikely job, and Stringer pursues legitimate business while Greggs watches how Marlo operates.","p":"/assets/stills/the-wire-s3e4.jpg"},{"t":"the-wire","s":3,"e":5,"n":"Straight and True","r":59,"y":"Frustrated by the drug war's futility, Colvin takes a radical idea directly to the corner bosses, while McNulty worries Stringer is slipping beyond the reach of police.","p":"/assets/stills/the-wire-s3e5.jpg"},{"t":"the-wire","s":3,"e":6,"n":"Homecoming","r":58,"y":"Stringer learns the hard realities of real estate development, Bunk tracks down Omar with a pointed message, and Avon dispatches Cutty and Slim Charles against Marlo.","p":"/assets/stills/the-wire-s3e6.jpg"},{"t":"the-wire","s":3,"e":7,"n":"Back Burners","r":56,"y":"Herc uncovers a connection from the past, Daniels learns why his detail was really reassigned, and Stringer gets worrying news about who might talk to McNulty.","p":"/assets/stills/the-wire-s3e7.jpg"},{"t":"the-wire","s":3,"e":8,"n":"Moral Midgetry","r":59,"y":"Colvin's experiment in tolerated drug zones gains momentum, Prez mines a cell phone for clues that send McNulty and Greggs on a road trip, and a community leader raises concerns.","p":"/assets/stills/the-wire-s3e8.jpg"},{"t":"the-wire","s":3,"e":9,"n":"Slapstick","r":59,"y":"McNulty and Prez answer an officer's call for help in a dark alley, and gunfire on a Sunday breaks a fragile peace among Baltimore's drug crews.","p":"/assets/stills/the-wire-s3e9.jpg"},{"t":"the-wire","s":3,"e":10,"n":"Reformation","r":59,"y":"Brother Mouzone returns to Baltimore seeking payback and hunts for Omar, while Colvin dodges a curious reporter and Daniels pursues a new kind of wiretap.","p":"/assets/stills/the-wire-s3e10.jpg"},{"t":"the-wire","s":3,"e":11,"n":"Middle Ground","r":59,"y":"The wiretap starts producing useful intelligence on the Barksdale organization, and Stringer and Avon look back on how far they have come together.","p":"/assets/stills/the-wire-s3e11.jpg"},{"t":"the-wire","s":3,"e":12,"n":"Mission Accomplished","r":64,"y":"In the season three finale, Avon prepares for war with Marlo, the detail closes in on the organization's top tier, and City Hall scrambles to contain Colvin's experiment.","p":"/assets/stills/the-wire-s3e12.jpg"},{"t":"the-wire","s":4,"e":1,"n":"Boys of Summer","r":59,"y":"As summer winds down, four West Baltimore boys look for ways to spend their last days of freedom, while Marlo tightens his grip and the detail pursues new subpoenas.","p":"/assets/stills/the-wire-s4e1.jpg"},{"t":"the-wire","s":4,"e":2,"n":"Soft Eyes","r":59,"y":"The mayoral race heats up with a high-profile debate, Freamon and Pearlman battle over their investigation, and Marlo makes a gesture toward neighborhood kids heading back to school.","p":"/assets/stills/the-wire-s4e2.jpg"},{"t":"the-wire","s":4,"e":3,"n":"Home Rooms","r":59,"y":"Former cop Prez faces his first class of middle schoolers, the mayoral campaign turns nasty, and Colvin tries his hand at a new civilian career.","p":"/assets/stills/the-wire-s4e3.jpg"},{"t":"the-wire","s":4,"e":4,"n":"Refugees","r":59,"y":"Personnel shuffles scatter the detail across new units, Cutty takes a job rounding up truant students, and Bubbles tries to get young Sherrod enrolled in school.","p":"/assets/stills/the-wire-s4e4.jpg"},{"t":"the-wire","s":4,"e":5,"n":"Alliances","r":59,"y":"Burrell's political support erodes, Marlo's enforcer Chris Partlow eyes Michael as a potential recruit, and the city's power brokers weigh a shift in the mayoral race.","p":"/assets/stills/the-wire-s4e5.jpg"},{"t":"the-wire","s":4,"e":6,"n":"Margin of Error","r":58,"y":"Councilman Carcetti scrambles to answer a campaign smear, Randy faces trouble at school, and Colvin's new classroom program welcomes its first students.","p":"/assets/stills/the-wire-s4e6.jpg"},{"t":"the-wire","s":4,"e":7,"n":"Unto Others","r":59,"y":"Omar calls on Bunk for help, Carcetti seeks counsel from political veterans, Prez finds a way to reach his students, and Bubbles keeps getting victimized on the street.","p":"/assets/stills/the-wire-s4e7.jpg"},{"t":"the-wire","s":4,"e":8,"n":"Corner Boys","r":59,"y":"Prez experiments with lessons outside the curriculum, Carcetti rides along with police, and Colvin's special class openly discusses the rules that govern life on the corner.","p":"/assets/stills/the-wire-s4e8.jpg"},{"t":"the-wire","s":4,"e":9,"n":"Know Your Place","r":59,"y":"Herc and Dozerman search for a missing street figure, Omar walks out of jail, Prez's school begins teaching to the test, and Carcetti meets the City Council.","p":"/assets/stills/the-wire-s4e9.jpg"},{"t":"the-wire","s":4,"e":10,"n":"Misgivings","r":59,"y":"Officer Walker punishes a young car thief, Burrell seeks advice from Senator Davis, a meeting with Marlo goes poorly, and Carver brings Namond in for questioning.","p":"/assets/stills/the-wire-s4e10.jpg"},{"t":"the-wire","s":4,"e":11,"n":"A New Day","r":59,"y":"Randy struggles with his friends after trouble at school, Carcetti faces a major dilemma as mayor-elect, Omar pays a visit to Proposition Joe, and Freamon shares a discovery.","p":"/assets/stills/the-wire-s4e11.jpg"},{"t":"the-wire","s":4,"e":12,"n":"That's Got His Own","r":59,"y":"Freamon bypasses his chain of command while searching for missing bodies, Carcetti confronts a school budget crisis, and Bubbles considers drastic measures against his tormentor.","p":"/assets/stills/the-wire-s4e12.jpg"},{"t":"the-wire","s":4,"e":13,"n":"Final Grades","r":79,"y":"In the fourth season finale, Burrell tries to help Daniels, Colvin looks for a way to help Namond, and Omar starts planning his next move.","p":"/assets/stills/the-wire-s4e13.jpg"},{"t":"the-wire","s":5,"e":1,"n":"More with Less","r":59,"y":"Budget cuts squeeze the police department and the newspaper alike, McNulty's team keeps watching Marlo, and Baltimore's drug kingpins gather to carve up territory.","p":"/assets/stills/the-wire-s5e1.jpg"},{"t":"the-wire","s":5,"e":2,"n":"Unconfirmed Reports","r":59,"y":"Freamon keeps tabs on Marlo, State Senator Clay Davis asks Burrell for help, and an editor at the Baltimore Sun plans an ambitious series on the city.","p":"/assets/stills/the-wire-s5e2.jpg"},{"t":"the-wire","s":5,"e":3,"n":"Not for Attribution","r":59,"y":"Carcetti's plans for the police department leak to the press, Marlo seeks Proposition Joe's help, and McNulty finds an unexpected partner in Freamon.","p":"/assets/stills/the-wire-s5e3.jpg"},{"t":"the-wire","s":5,"e":4,"n":"Transitions","r":59,"y":"Omar returns from exile bent on revenge, Sun editor Gus Haynes pushes for better court coverage, and Carcetti finds conditions attached to removing Burrell.","p":"/assets/stills/the-wire-s5e4.jpg"},{"t":"the-wire","s":5,"e":5,"n":"React Quotes","r":59,"y":"Marlo's crew braces for Omar while Marlo celebrates a deal, McNulty and Freamon exploit a development in a homeless murder case, and Dukie visits Cutty's gym.","p":"/assets/stills/the-wire-s5e5.jpg"},{"t":"the-wire","s":5,"e":6,"n":"The Dickensian Aspect","r":59,"y":"Marlo's people go on high alert, Carcetti turns attention to the homeless, Bunk interviews a witness tied to the row-house killings, and a reporter chases a follow-up story.","p":"/assets/stills/the-wire-s5e6.jpg"},{"t":"the-wire","s":5,"e":7,"n":"Took","r":59,"y":"The homeless murder case turns McNulty and Freamon into unlikely heroes, Clay Davis lines up top legal help for his trial, and Michael has close calls with the law.","p":"/assets/stills/the-wire-s5e7.jpg"},{"t":"the-wire","s":5,"e":8,"n":"Clarifications","r":59,"y":"A transfer sends Carver to a new post, Carcetti weighs a move that risks his political future, Haynes scrutinizes a reporter's work, and Sydnor makes progress on a case.","p":"/assets/stills/the-wire-s5e8.jpg"},{"t":"the-wire","s":5,"e":9,"n":"Late Editions","r":60,"y":"A promising lead rewards Freamon's patience, Michael grows wary of his latest assignment, Haynes brings in help with fact-checking, and Namond impresses Colvin at a debate.","p":"/assets/stills/the-wire-s5e9.jpg"},{"t":"the-wire","s":5,"e":10,"n":"-30-","r":94,"y":"In the series finale, a damaging report draws a reaction from City Hall, McNulty tries to close the homeless case, and Dukie seeks out an old mentor.","p":"/assets/stills/the-wire-s5e10.jpg"},{"t":"six-feet-under","s":1,"e":1,"n":"Pilot","r":63,"y":"Nate Fisher comes home to Los Angeles for Christmas and is swept back into his family's funeral home after devastating news about his father.","p":"/assets/stills/six-feet-under-s1e1.jpg"},{"t":"six-feet-under","s":1,"e":2,"n":"The Will","r":52,"y":"While the Fishers gather for the reading of their father's will, Nate shows compassion to a widow left in debt by her husband's failed business scheme.","p":"/assets/stills/six-feet-under-s1e2.jpg"},{"t":"six-feet-under","s":1,"e":3,"n":"The Foot","r":53,"y":"A gruesome industrial accident challenges Federico's restorative skills, while a large corporate funeral chain makes the Fishers a tempting offer to buy the family business.","p":"/assets/stills/six-feet-under-s1e3.jpg"},{"t":"six-feet-under","s":1,"e":4,"n":"Familia","r":52,"y":"The Fishers handle the funeral of a young gang member whose family and crew want very different services, and Brenda meets Nate's family over an awkward dinner.","p":"/assets/stills/six-feet-under-s1e4.jpg"},{"t":"six-feet-under","s":1,"e":5,"n":"An Open Book","r":55,"y":"The wake of an adult film actress brings unusual mourners to the funeral home, Nate meets Brenda's unpredictable brother Billy, and David pursues a role at church.","p":"/assets/stills/six-feet-under-s1e5.jpg"},{"t":"six-feet-under","s":1,"e":6,"n":"The Room","r":58,"y":"A lonely widower refuses to leave the funeral home, Claire grows close to Billy, Ruth fields attention from two different suitors, and the business books reveal surprises.","p":"/assets/stills/six-feet-under-s1e6.jpg"},{"t":"six-feet-under","s":1,"e":7,"n":"Brotherhood","r":51,"y":"A young veteran's brother requests a bare-bones cremation, Ruth takes a job at a flower 